:root {
  color-scheme: light;
  --ink: #17211c;
  --muted: #647067;
  --line: #dce5de;
  --paper: #fbfcf8;
  --panel: #ffffff;
  --field: #0f6b4f;
  --field-dark: #084434;
  --lime: #b8d84c;
  --gold: #f6c453;
  --rust: #b55228;
  --blue: #34699a;
  --danger: #b91c1c;
  --shadow: 0 18px 50px rgba(23, 33, 28, 0.12);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

* {
  box-sizing: border-box;
}

html {
  max-width: 100%;
  overflow-x: hidden;
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-width: 0;
  width: 100%;
  max-width: 100%;
  overflow-x: hidden;
  background: var(--paper);
  color: var(--ink);
}

body:has(.admin-route-shell) {
  background: #020811;
}

#app {
  width: 100%;
  max-width: 100%;
  overflow-x: hidden;
}

.app-shell {
  width: 100%;
  max-width: 100%;
  min-height: 100vh;
  overflow-x: clip;
}

.public-route-shell {
  padding-top: 78px;
  background:
    radial-gradient(circle at 8% 0%, rgba(0, 99, 255, 0.24), transparent 34%),
    radial-gradient(circle at 92% 8%, rgba(89, 255, 0, 0.2), transparent 32%),
    linear-gradient(180deg, #06111f 0%, #071724 330px, var(--paper) 660px);
}

.public-route-shell.public-entry-shell {
  padding-top: 0;
}

button,
input,
select,
textarea {
  font: inherit;
}

button,
a.primary,
a.secondary {
  min-height: 42px;
  border: 0;
  border-radius: 8px;
  cursor: pointer;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 16px;
  font-weight: 800;
}

button {
  background: #eef4ed;
  color: var(--ink);
}

button:hover,
a:hover {
  filter: brightness(0.98);
}

.primary {
  background: var(--field);
  color: #fff;
}

.secondary {
  background: rgba(255, 255, 255, 0.16);
  border: 1px solid rgba(255, 255, 255, 0.44);
  color: #fff;
}

.danger {
  background: #fee2e2;
  color: var(--danger);
}

.ghost-danger {
  background: #fff;
  border: 1px solid #fecaca;
  color: var(--danger);
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px clamp(16px, 4vw, 44px);
  background: rgba(251, 252, 248, 0.92);
  border-bottom: 1px solid var(--line);
  backdrop-filter: blur(14px);
}

.public-topbar {
  position: fixed;
  inset: 0 0 auto;
  display: grid;
  grid-template-columns: minmax(230px, 0.9fr) minmax(280px, auto) minmax(120px, 0.9fr);
  align-items: center;
  justify-content: stretch;
  gap: clamp(12px, 2.4vw, 28px);
  min-height: 78px;
  padding-block: 10px;
  background:
    linear-gradient(90deg, rgba(3, 10, 19, 0.96), rgba(6, 17, 31, 0.9), rgba(3, 18, 20, 0.96));
  border-bottom-color: rgba(72, 255, 172, 0.22);
  box-shadow: 0 18px 48px rgba(2, 8, 23, 0.22);
  transform: translateY(0);
  transition: transform 220ms ease, box-shadow 220ms ease;
  will-change: transform;
}

.public-topbar-hidden {
  transform: translateY(calc(-100% - 12px));
  box-shadow: none;
}

.admin-topbar {
  align-items: center;
  padding: 10px clamp(12px, 3vw, 28px);
  border-bottom: 1px solid rgba(91, 255, 137, 0.18);
  background:
    radial-gradient(circle at 4% 0%, rgba(91, 255, 137, 0.16), transparent 28%),
    linear-gradient(90deg, rgba(2, 10, 17, 0.98), rgba(4, 26, 29, 0.96), rgba(2, 16, 12, 0.98));
  box-shadow: 0 18px 48px rgba(0, 0, 0, 0.24);
}

.admin-topbar .brand {
  min-width: 205px;
  color: #f7fbff;
}

.admin-topbar .brand-mark-logo {
  width: 54px;
  height: 54px;
  border-radius: 14px;
  box-shadow: 0 12px 28px rgba(37, 255, 130, 0.16);
}

.admin-topbar .brand-copy small {
  color: rgba(220, 232, 240, 0.72);
}

.private-topbar-actions {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(190px, 300px) minmax(280px, 1fr) auto minmax(210px, auto);
  gap: 9px;
  align-items: center;
}

.private-league-switcher {
  min-width: 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 8px;
  align-items: center;
  min-height: 48px;
  padding: 7px 10px;
  border: 1px solid rgba(132, 166, 190, 0.14);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.06);
}

.private-league-switcher span {
  color: #8cff5a;
  font-size: 0.68rem;
  font-weight: 1000;
  text-transform: uppercase;
}

.private-league-switcher select {
  min-height: 34px;
  padding: 0 28px 0 10px;
  border: 0;
  border-radius: 10px;
  background: rgba(2, 10, 17, 0.56);
  color: #fff;
  font-size: 0.84rem;
  font-weight: 950;
  text-transform: uppercase;
}

.private-panel-nav {
  min-width: 0;
  display: flex;
  gap: 7px;
  align-items: center;
  padding: 5px;
  border: 1px solid rgba(91, 255, 137, 0.14);
  border-radius: 15px;
  background: rgba(2, 10, 17, 0.54);
  overflow-x: auto;
  scrollbar-width: none;
}

.private-panel-nav::-webkit-scrollbar {
  display: none;
}

.private-panel-nav button,
.private-panel-link {
  min-width: max-content;
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 10px;
  border: 1px solid transparent;
  border-radius: 11px;
  background: transparent;
  color: rgba(220, 232, 240, 0.76);
  font-size: 0.76rem;
  font-weight: 950;
  text-decoration: none;
  white-space: nowrap;
}

.private-panel-nav button span,
.private-panel-link span {
  width: 24px;
  height: 24px;
  display: inline-grid;
  place-items: center;
  border-radius: 8px;
  background: rgba(140, 247, 76, 0.1);
  color: #8cff5a;
}

.private-panel-nav button.active {
  border-color: transparent;
  background: linear-gradient(135deg, #22d847, #20e7c5);
  color: #06110d;
}

.private-panel-nav button.active span {
  background: rgba(0, 0, 0, 0.1);
  color: #06110d;
}

.private-panel-link {
  border-color: rgba(35, 180, 255, 0.22);
  color: #9ad7ff;
  background: rgba(35, 180, 255, 0.08);
}

.private-panel-link span {
  color: #9ad7ff;
  background: rgba(35, 180, 255, 0.12);
}

.private-api-pill {
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 11px;
  border-radius: 999px;
  border: 1px solid rgba(140, 247, 76, 0.22);
  color: #8cff5a;
  background: rgba(140, 247, 76, 0.1);
  font-size: 0.68rem;
  font-weight: 1000;
  text-transform: uppercase;
  white-space: nowrap;
}

.private-user-chip {
  min-width: 0;
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) auto;
  gap: 9px;
  align-items: center;
  min-height: 48px;
  padding: 5px 5px 5px 7px;
  border: 1px solid rgba(132, 166, 190, 0.16);
  border-radius: 15px;
  background: rgba(255, 255, 255, 0.06);
}

.private-user-avatar {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  color: #06110d;
  background: linear-gradient(135deg, #8cff5a, #20e7c5);
  font-size: 0.78rem;
  font-weight: 1000;
}

.private-user-chip strong,
.private-user-chip small {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.private-user-chip strong {
  color: #fff;
  font-size: 0.82rem;
  font-weight: 1000;
}

.private-user-chip small {
  color: rgba(220, 232, 240, 0.62);
  font-size: 0.68rem;
  font-weight: 850;
}

.private-user-chip button {
  min-height: 38px;
  padding: 0 12px;
  border: 1px solid rgba(132, 166, 190, 0.16);
  border-radius: 11px;
  color: #f7fbff;
  background: rgba(255, 255, 255, 0.08);
  font-size: 0.74rem;
  font-weight: 950;
}

.startup-screen {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background-color: #020712;
  background:
    linear-gradient(rgba(12, 24, 18, 0.58), rgba(12, 24, 18, 0.66)),
    url("../assets/league-hero.webp") center/cover;
}

.startup-card {
  display: grid;
  justify-items: center;
  gap: 10px;
  width: min(320px, 100%);
  padding: 24px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 8px;
  color: #fff;
  text-align: center;
  background: rgba(12, 24, 18, 0.72);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.22);
}

.startup-card strong {
  font-size: 1.18rem;
}

.startup-card small {
  color: rgba(255, 255, 255, 0.78);
}

.inline-loading,
.auth-loading {
  display: inline-flex;
  align-items: center;
  min-height: 40px;
  color: var(--muted);
  font-size: 0.9rem;
}

.portal-loading-page {
  min-height: 100svh;
  display: grid;
  place-items: center;
  padding: 18px;
  background:
    radial-gradient(circle at 50% 0%, rgba(91, 255, 137, 0.16), transparent 34%),
    linear-gradient(180deg, #031018, #02080d 68%);
}

.portal-loading-card {
  width: min(100%, 380px);
  display: grid;
  justify-items: center;
  gap: 9px;
  padding: 28px 22px;
  border: 1px solid rgba(91, 255, 137, 0.22);
  border-radius: 22px;
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.075), rgba(255, 255, 255, 0.035)),
    rgba(5, 17, 25, 0.92);
  color: #f7fbff;
  text-align: center;
  box-shadow: 0 24px 58px rgba(0, 0, 0, 0.36), inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.portal-loading-card img {
  width: 70px;
  height: 70px;
  object-fit: cover;
  border-radius: 18px;
  box-shadow: 0 16px 34px rgba(0, 0, 0, 0.28);
}

.portal-loading-card span {
  margin-top: 4px;
  color: #91ff58;
  font-size: 0.68rem;
  font-weight: 1000;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.portal-loading-card strong {
  color: #fff;
  font-size: 1.22rem;
  font-weight: 1000;
}

.portal-loading-card small {
  max-width: 260px;
  color: rgba(255, 255, 255, 0.66);
  font-size: 0.78rem;
  font-weight: 850;
  line-height: 1.35;
}

.portal-loading-bars {
  width: 100%;
  display: grid;
  gap: 8px;
  margin-top: 10px;
}

.portal-loading-bars b {
  display: block;
  height: 10px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.07);
}

.portal-loading-bars b::after {
  content: "";
  display: block;
  width: 46%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, transparent, rgba(145, 255, 88, 0.72), transparent);
  animation: portalLoadingSweep 1.25s ease-in-out infinite;
}

.portal-loading-bars b:nth-child(2)::after {
  animation-delay: 0.12s;
}

.portal-loading-bars b:nth-child(3)::after {
  animation-delay: 0.24s;
}

.portal-loading-card.referee {
  border-color: rgba(89, 167, 255, 0.24);
}

.portal-loading-card.referee span {
  color: #77baff;
}

.portal-loading-card.referee .portal-loading-bars b::after {
  background: linear-gradient(90deg, transparent, rgba(89, 167, 255, 0.72), transparent);
}

@keyframes portalLoadingSweep {
  0% {
    transform: translateX(-110%);
  }

  100% {
    transform: translateX(230%);
  }
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  color: var(--ink);
  text-decoration: none;
}

.public-topbar .brand {
  color: #fff;
}

.public-brand-zone {
  width: auto;
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: flex-start;
}

.public-brand-zone .brand {
  width: auto;
  align-items: center;
  justify-self: center;
}

.public-header-shortcuts {
  justify-self: center;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: max-content;
  max-width: 100%;
  min-width: 0;
  padding: 5px;
  border: 1px solid rgba(42, 231, 188, 0.18);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.045);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.public-logo-home-link,
.public-header-tournament-button,
.public-header-search-button {
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 15px;
  border: 1px solid rgba(141, 255, 68, 0.28);
  border-radius: 999px;
  background: rgba(141, 255, 68, 0.1);
  color: color-mix(in srgb, var(--lime) 84%, #fff);
  font: inherit;
  font-size: 0.75rem;
  font-weight: 950;
  line-height: 1;
  text-decoration: none;
  text-transform: uppercase;
  white-space: nowrap;
  box-shadow: none;
}

.public-header-tournament-button {
  border-color: rgba(42, 231, 188, 0.34);
  background:
    linear-gradient(135deg, rgba(42, 231, 188, 0.11), rgba(141, 255, 68, 0.08)),
    rgba(255, 255, 255, 0.035);
  color: rgba(219, 255, 243, 0.94);
  cursor: pointer;
}

.public-header-search-button {
  width: 42px;
  padding: 0;
  border-color: rgba(42, 231, 188, 0.34);
  background: rgba(255, 255, 255, 0.045);
  cursor: pointer;
}

.public-header-search-button span {
  position: relative;
  width: 15px;
  height: 15px;
  display: block;
  border: 2px solid color-mix(in srgb, var(--lime) 84%, #fff);
  border-radius: 999px;
}

.public-header-search-button span::after {
  content: "";
  position: absolute;
  right: -6px;
  bottom: -5px;
  width: 8px;
  height: 2px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--lime) 84%, #fff);
  transform: rotate(45deg);
}

.public-logo-home-link:hover,
.public-logo-home-link:focus-visible,
.public-header-tournament-button:hover,
.public-header-tournament-button:focus-visible,
.public-header-search-button:hover,
.public-header-search-button:focus-visible {
  border-color: rgba(141, 255, 68, 0.62);
  background: rgba(141, 255, 68, 0.16);
  color: #fff;
}

.brand-mark {
  width: 50px;
  height: 50px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  overflow: hidden;
  color: #fff;
  background: linear-gradient(135deg, var(--field), var(--blue));
  font-weight: 900;
}

.brand-mark-logo {
  padding: 0;
  border: 1px solid rgba(126, 255, 84, 0.22);
  background: #020405;
  box-shadow:
    0 12px 26px rgba(0, 162, 255, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.16);
}

.brand-mark-logo img {
  width: 100%;
  height: 100%;
  display: block;
  border-radius: 6px;
  object-fit: cover;
  object-position: center;
}

.startup-card .brand-mark {
  width: 76px;
  height: 76px;
}

.brand strong,
.brand small {
  display: block;
}

.brand-copy {
  display: grid;
  gap: 1px;
  line-height: 1;
}

.brand-wordmark {
  color: currentColor;
  font-size: clamp(1.18rem, 2.4vw, 1.72rem);
  font-style: italic;
  font-weight: 950;
  letter-spacing: 0.06em;
  line-height: 0.94;
}

.brand-wordmark span {
  color: #50f043;
  background: linear-gradient(90deg, #18f5c1, #67f533);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.brand small,
.league-switcher span,
.eyebrow {
  color: var(--muted);
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0;
  text-transform: uppercase;
}

.public-topbar .brand small,
.public-topbar .public-league-badge span {
  color: rgba(255, 255, 255, 0.72);
}

.public-topbar .brand small {
  font-size: 0.7rem;
  letter-spacing: 0.08em;
}

.topbar-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.public-topbar .topbar-actions {
  flex: 0 0 auto;
  margin-left: auto;
  align-self: center;
  justify-self: end;
}

.admin-public-link {
  min-height: 34px;
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--ink);
  font-weight: 800;
  padding: 0 12px;
  text-decoration: none;
}

.public-topbar .admin-public-link {
  border-color: rgba(72, 255, 172, 0.28);
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
}

.public-topbar .public-home-link {
  border-color: rgba(141, 255, 68, 0.38);
  background: rgba(141, 255, 68, 0.1);
  color: color-mix(in srgb, var(--lime) 82%, #fff);
}

.access-ligatec-link {
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 13px;
  border: 1px solid rgba(141, 255, 68, 0.58);
  border-radius: 999px;
  color: #fff;
  text-decoration: none;
  background:
    linear-gradient(135deg, rgba(0, 174, 255, 0.1), rgba(101, 245, 51, 0.13)),
    rgba(255, 255, 255, 0.05);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.access-ligatec-link span:last-child {
  display: grid;
  gap: 2px;
}

.access-ligatec-link strong,
.access-ligatec-link small {
  display: block;
  line-height: 1.05;
}

.access-ligatec-link strong {
  font-size: 0.74rem;
  font-weight: 950;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.access-ligatec-link small {
  color: rgba(255, 255, 255, 0.72);
  font-size: 0.78rem;
  font-weight: 800;
}

.access-link-mark,
.access-lock-icon {
  position: relative;
  width: 18px;
  height: 16px;
  flex: 0 0 auto;
  border: 2px solid #9df64d;
  border-radius: 5px;
}

.access-link-mark::before,
.access-lock-icon::before {
  content: "";
  position: absolute;
  left: 4px;
  top: -10px;
  width: 7px;
  height: 10px;
  border: 2px solid #9df64d;
  border-bottom: 0;
  border-radius: 10px 10px 0 0;
}

.access-link-mark::after,
.access-lock-icon::after {
  content: "";
  position: absolute;
  right: 5px;
  bottom: 5px;
  width: 4px;
  height: 4px;
  border: 0;
  border-radius: 999px;
  background: #9df64d;
}

.auth-panel {
  display: grid;
  grid-template-columns: 180px 130px auto auto;
  gap: 8px;
  align-items: center;
}

.auth-panel.recovery {
  grid-template-columns: 180px 100px 150px auto auto;
}

.auth-panel input {
  min-height: 34px;
  padding: 6px 10px;
}

.auth-panel button {
  min-height: 34px;
}

.auth-panel.signed-in {
  grid-template-columns: minmax(130px, auto) auto;
  padding: 6px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
}

.auth-panel strong,
.auth-panel small {
  display: block;
}

.auth-panel small {
  color: var(--muted);
  font-size: 0.75rem;
  font-weight: 800;
}

.auth-help {
  grid-column: 1 / -1;
  color: var(--muted);
}

.auth-error {
  grid-column: 1 / -1;
  color: var(--danger);
  font-weight: 800;
}

.auth-ok {
  grid-column: 1 / -1;
  color: var(--field);
  font-weight: 800;
  white-space: pre-line;
}

.inline-feedback {
  margin: 0;
  padding: 8px 10px;
  border-radius: 8px;
  background: #eef6f2;
}

.auth-error.inline-feedback {
  background: #fff1f1;
}

.admin-access-page {
  min-height: calc(100vh - 78px);
  display: grid;
  place-items: center;
}

.admin-access-card {
  width: min(100%, 680px);
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  box-shadow: var(--shadow);
  padding: clamp(22px, 4vw, 36px);
}

.admin-access-card h1 {
  margin: 6px 0 8px;
  font-size: clamp(2rem, 4vw, 3.2rem);
}

.admin-access-card p {
