.intro-animation {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: grid;
  place-items: center;
  min-width: 0;
  padding: 24px;
  background:
    radial-gradient(circle at 50% 18%, rgba(140, 247, 76, 0.18), transparent 28%),
    radial-gradient(circle at 16% 12%, rgba(0, 110, 255, 0.2), transparent 25%),
    radial-gradient(circle at 88% 18%, rgba(140, 247, 76, 0.12), transparent 24%),
    linear-gradient(145deg, #020712, #06111f 52%, #031812),
    #020712;
  color: #fff;
  opacity: 1;
  overflow: hidden;
  pointer-events: auto;
  animation: introFadeIn 220ms ease-out both;
}

.intro-animation.is-leaving {
  animation: introFadeOut 420ms ease-in both;
}

.intro-stadium-lights,
.intro-field-lines {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.intro-stadium-lights {
  background:
    radial-gradient(ellipse at 18% 0%, rgba(255, 255, 255, 0.26), transparent 26%),
    radial-gradient(ellipse at 82% 0%, rgba(255, 255, 255, 0.2), transparent 26%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.06), transparent 42%);
  opacity: 0.82;
  animation: introLights 1700ms ease-out both;
}

.intro-field-lines {
  inset: 12%;
  border: 1px solid rgba(140, 247, 76, 0.22);
  border-radius: 8px;
  background:
    linear-gradient(90deg, transparent calc(50% - 1px), rgba(140, 247, 76, 0.22) 50%, transparent calc(50% + 1px)),
    radial-gradient(circle at center, transparent 0 19%, rgba(140, 247, 76, 0.18) 20% 20.8%, transparent 21%),
    linear-gradient(0deg, transparent calc(50% - 1px), rgba(140, 247, 76, 0.12) 50%, transparent calc(50% + 1px));
  opacity: 0;
  transform: perspective(900px) rotateX(58deg) translateY(8%);
  animation: introFieldReveal 1100ms 120ms ease-out both;
}

.intro-content {
  position: relative;
  z-index: 2;
  display: grid;
  justify-items: center;
  gap: 8px;
  min-width: 0;
  text-align: center;
  animation: introLogoReveal 950ms 220ms cubic-bezier(0.2, 0.9, 0.2, 1) both;
}

.intro-logo-frame {
  width: clamp(92px, 28vw, 136px);
  height: clamp(92px, 28vw, 136px);
  display: grid;
  place-items: center;
  overflow: hidden;
  border: 1px solid rgba(140, 247, 76, 0.26);
  border-radius: 28px;
  background: rgba(255, 255, 255, 0.04);
  box-shadow:
    0 0 0 8px rgba(140, 247, 76, 0.04),
    0 28px 72px rgba(0, 0, 0, 0.34),
    0 0 42px rgba(140, 247, 76, 0.18);
}

.intro-logo-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.intro-content strong {
  color: #fff;
  font-size: clamp(2.4rem, 10vw, 5rem);
  font-style: italic;
  font-weight: 950;
  letter-spacing: 0.04em;
  line-height: 0.92;
  text-shadow: 0 0 28px rgba(140, 247, 76, 0.22);
}

.intro-content p {
  margin: 0;
  color: rgba(239, 252, 247, 0.82);
  font-size: clamp(0.98rem, 4vw, 1.25rem);
  font-weight: 850;
}

.intro-dev {
  position: absolute;
  right: clamp(16px, 4vw, 34px);
  bottom: clamp(16px, 4vw, 28px);
  z-index: 2;
  display: grid;
  justify-items: end;
  gap: 5px;
  min-width: 0;
  color: rgba(239, 252, 247, 0.66);
  font-size: 0.72rem;
  font-weight: 850;
  text-transform: uppercase;
  animation: introDevReveal 560ms 920ms ease-out both;
}

.intro-dev img {
  width: clamp(118px, 25vw, 180px);
  height: auto;
  max-height: 70px;
  object-fit: contain;
  opacity: 0.9;
}

.intro-skip {
  position: absolute;
  top: 14px;
  right: 14px;
  z-index: 3;
  min-height: 36px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 999px;
  padding: 0 12px;
  background: rgba(255, 255, 255, 0.08);
  color: rgba(239, 252, 247, 0.72);
  font-size: 0.72rem;
  font-weight: 900;
}

@keyframes introFadeIn {
  from {
    opacity: 0;
  }
}

@keyframes introFadeOut {
  to {
    opacity: 0;
    visibility: hidden;
  }
}

@keyframes introFieldReveal {
  from {
    opacity: 0;
    transform: perspective(900px) rotateX(63deg) translateY(18%) scale(0.94);
  }
  to {
    opacity: 1;
  }
}

@keyframes introLogoReveal {
  from {
    filter: blur(10px);
    opacity: 0;
    transform: translateY(10px) scale(0.92);
  }
  70% {
    filter: blur(0);
    opacity: 1;
    transform: translateY(0) scale(1.035);
  }
  to {
    filter: blur(0);
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes introLights {
  from {
    opacity: 0;
    transform: scale(1.04);
  }
}

@keyframes introDevReveal {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
  }
}

