.public-quick-nav {
  position: sticky;
  top: 74px;
  z-index: 12;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
  margin: 16px auto 0;
  padding: 7px;
  width: min(100%, 680px);
  border: 1px solid rgba(42, 231, 188, 0.26);
  border-radius: 22px;
  background:
    radial-gradient(circle at 10% 0%, rgba(140, 247, 76, 0.2), transparent 34%),
    radial-gradient(circle at 92% 100%, rgba(42, 231, 188, 0.16), transparent 32%),
    linear-gradient(135deg, rgba(4, 20, 25, 0.96), rgba(4, 63, 54, 0.94));
  box-shadow:
    0 18px 46px rgba(2, 12, 20, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.16);
  backdrop-filter: blur(18px) saturate(1.25);
}

.public-quick-nav button {
  position: relative;
  min-width: 0;
  min-height: 54px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  overflow: hidden;
  padding: 6px 8px;
  border: 1px solid transparent;
  border-radius: 16px;
  appearance: none;
  background: transparent;
  color: rgba(196, 255, 238, 0.82);
  cursor: pointer;
  font-size: 0.76rem;
  font-family: inherit;
  font-weight: 950;
  letter-spacing: 0;
  text-transform: uppercase;
  transition: transform 180ms ease, background-color 180ms ease, border-color 180ms ease, box-shadow 180ms ease, color 180ms ease;
  -webkit-tap-highlight-color: transparent;
}

.public-quick-nav button::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  background:
    linear-gradient(135deg, rgba(140, 247, 76, 0.98), rgba(42, 231, 188, 0.88));
  opacity: 0;
  transform: scale(0.9);
  transition: opacity 180ms ease, transform 180ms ease;
}

.public-quick-nav button:hover,
.public-quick-nav button:focus-visible {
  border-color: rgba(42, 231, 188, 0.34);
  background: rgba(255, 255, 255, 0.1);
  box-shadow: 0 10px 24px rgba(2, 12, 20, 0.16);
  transform: translateY(-1px);
}

.public-quick-nav button.active,
.public-quick-nav button[aria-current="page"] {
  border-color: rgba(140, 247, 76, 0.62);
  color: #03130f;
  box-shadow:
    0 10px 22px rgba(42, 231, 188, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.42);
}

.public-quick-nav button.active::before,
.public-quick-nav button[aria-current="page"]::before {
  opacity: 1;
  transform: scale(1);
}

.public-quick-nav button:active {
  transform: translateY(0) scale(0.98);
}

.quick-nav-icon {
  width: 34px;
  height: 34px;
  display: inline-grid;
  place-items: center;
  flex: 0 0 auto;
  color: #2ae7bc;
  filter: drop-shadow(0 0 10px rgba(42, 231, 188, 0.22));
  transition: transform 180ms ease, color 180ms ease, filter 180ms ease;
}

.quick-nav-icon svg {
  width: 30px;
  height: 30px;
  display: block;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.95;
}

.public-quick-nav button.active .quick-nav-icon,
.public-quick-nav button[aria-current="page"] .quick-nav-icon {
  color: #05231a;
  filter: drop-shadow(0 2px 6px rgba(3, 19, 15, 0.18));
}

.public-quick-nav button:active .quick-nav-icon {
  transform: scale(0.96);
}

