  display: flex;
  gap: 8px;
  margin-bottom: 12px;
  overflow-x: auto;
  padding: 2px 2px 6px;
  scroll-padding-inline: 50%;
  scroll-behavior: smooth;
  scrollbar-width: thin;
}

.round-tabs button {
  min-width: 58px;
  min-height: 42px;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  flex: 0 0 auto;
  background: #f7faf6;
  border: 1px solid var(--line);
  box-shadow: inset 0 -2px 0 rgba(15, 107, 79, 0.06);
}

.round-tabs button span {
  line-height: 1;
}

.round-tabs button small {
  display: block;
  color: currentColor;
  font-size: 0.54rem;
  font-weight: 950;
  letter-spacing: 0;
  line-height: 1;
  opacity: 0.68;
  text-transform: uppercase;
}

.round-tabs .active {
  background: var(--field);
  color: #fff;
  border-color: color-mix(in srgb, var(--lime) 62%, var(--field));
  box-shadow:
    0 10px 22px rgba(15, 107, 79, 0.26),
    0 0 0 2px color-mix(in srgb, var(--lime) 42%, transparent);
}

.round-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fbfdfb;
}

.round-summary span {
  color: var(--muted);
  font-weight: 800;
}

.competition-panel {
  margin-top: -10px;
}

.public-competition-panel {
  margin-top: 8px;
  border-top-width: 0;
  background:
    radial-gradient(circle at top right, color-mix(in srgb, var(--lime) 18%, transparent), transparent 36%),
    linear-gradient(135deg, #ffffff, #f6fbf8);
}

.competition-picker {
  display: grid;
  gap: 14px;
}

.competition-choice-group {
  display: grid;
  gap: 8px;
}

.competition-choice-group > span {
  color: var(--muted);
  font-size: 0.74rem;
  font-weight: 950;
  text-transform: uppercase;
}

.competition-button-row {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding: 2px 2px 10px;
  scrollbar-width: thin;
}

.competition-button-row button {
  min-height: 52px;
  min-width: 150px;
  flex: 0 0 auto;
  display: grid;
  gap: 2px;
  align-content: center;
  justify-items: start;
  padding: 10px 14px;
  border: 1px solid color-mix(in srgb, var(--field) 18%, var(--line));
  border-radius: 8px;
  background:
    radial-gradient(circle at 100% 0%, color-mix(in srgb, var(--lime) 14%, transparent), transparent 48%),
    linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(248, 252, 247, 0.9));
  color: color-mix(in srgb, var(--field-dark) 90%, #111827);
  text-align: left;
  white-space: nowrap;
  box-shadow: 0 8px 18px rgba(23, 33, 28, 0.06);
}

.competition-button-row button.active {
  border-color: color-mix(in srgb, var(--lime) 56%, var(--field));
  background:
    linear-gradient(135deg, #0877ff, #139e83 56%, #8cf74c);
  color: #fff;
  box-shadow: 0 14px 28px rgba(15, 107, 79, 0.22);
}

.competition-button-row button strong,
.competition-button-row button small {
  display: block;
}

.competition-button-row button small {
  color: currentColor;
  font-size: 0.68rem;
  font-weight: 850;
  opacity: 0.78;
  text-transform: uppercase;
}

.competition-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 12px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fbfdfb;
}

.competition-summary span {
  color: var(--muted);
  font-weight: 900;
  text-transform: uppercase;
}

.tournament-selector {
  position: relative;
  display: grid;
  gap: 18px;
  min-width: 0;
  overflow: hidden;
  padding: clamp(16px, 4vw, 28px);
  border: 1px solid color-mix(in srgb, var(--competition-accent) 36%, rgba(13, 84, 65, 0.2));
  border-radius: 8px;
  background:
    radial-gradient(circle at 91% 16%, rgba(13, 115, 89, 0.08), transparent 18%),
    radial-gradient(circle at 98% 18%, rgba(11, 78, 63, 0.06) 0 58px, transparent 60px),
    linear-gradient(135deg, #ffffff, #f7fffb);
  box-shadow: 0 18px 40px rgba(2, 12, 14, 0.1);
}

.tournament-selector::after {
  content: "";
  position: absolute;
  top: 34px;
  right: clamp(18px, 6vw, 54px);
  width: clamp(72px, 19vw, 130px);
  height: clamp(72px, 19vw, 130px);
  border: 10px solid color-mix(in srgb, var(--field) 12%, transparent);
  border-radius: 50%;
  box-shadow:
    inset 0 0 0 18px color-mix(in srgb, var(--field) 6%, transparent),
    0 44px 0 -30px color-mix(in srgb, var(--field) 12%, transparent);
  opacity: 0.16;
  pointer-events: none;
}

.tournament-selector-head {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 8px;
  max-width: 560px;
}

.tournament-selector-head > span {
  width: fit-content;
  max-width: 100%;
  min-height: 34px;
  display: inline-flex;
  align-items: center;
  padding: 0 14px;
  border-radius: 8px;
  background: color-mix(in srgb, var(--lime) 26%, #dffff0);
  color: var(--field);
  font-size: clamp(0.78rem, 2.8vw, 0.94rem);
  font-weight: 950;
  text-transform: uppercase;
}

.tournament-selector-head h2 {
  margin: 0;
  color: #071816;
  font-size: clamp(2rem, 9vw, 3.6rem);
  line-height: 1;
  letter-spacing: 0;
}

.tournament-selector-head p {
  max-width: 420px;
  margin: 0;
  color: #34454a;
  font-size: clamp(0.96rem, 3.5vw, 1.1rem);
  font-weight: 750;
  line-height: 1.45;
}

.tournament-selector-layout {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 16px;
}

.season-select-block,
.category-select-block {
  display: grid;
  gap: 10px;
  min-width: 0;
}

.selector-step-label {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  color: #35464a;
  font-size: clamp(1rem, 3.7vw, 1.18rem);
  font-weight: 950;
  text-transform: uppercase;
}

.selector-step-label b {
  width: 34px;
  height: 34px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: linear-gradient(135deg, #21dd8a, #99ff43);
  color: #06201a;
  box-shadow: 0 10px 22px rgba(33, 221, 138, 0.24);
}

.selector-step-label span {
  min-width: 0;
  overflow-wrap: anywhere;
  letter-spacing: 0.02em;
}

.season-select-button {
  width: 100%;
  min-height: 64px;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto 28px;
  gap: 12px;
  align-items: center;
  padding: 10px 12px;
  border: 1.5px solid color-mix(in srgb, var(--field) 72%, #c7ddd5);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.94);
  color: #071816;
  text-align: left;
  box-shadow: 0 10px 22px rgba(1, 20, 17, 0.06);
}

.season-select-button:hover,
.season-select-button:focus-visible,
.category-option:hover,
.category-option:focus-visible,
.category-show-all-button:hover,
.category-show-all-button:focus-visible,
.tournament-sheet-list button:hover,
.tournament-sheet-list button:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--lime) 42%, transparent);
  outline-offset: 2px;
}

.season-select-button:active,
.category-option:active,
.category-show-all-button:active,
.tournament-sheet-list button:active {
  transform: translateY(1px) scale(0.995);
}

.season-select-icon {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border: 2px solid var(--field);
  border-top-width: 6px;
  border-radius: 8px;
  color: var(--field);
}

.season-select-icon::before,
.season-select-icon::after {
  content: "";
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 9px 0 0 currentColor, 18px 0 0 currentColor, 0 9px 0 currentColor, 9px 9px 0 currentColor;
}

.season-select-button strong {
  min-width: 0;
  overflow-wrap: anywhere;
  color: #071816;
  font-size: clamp(1.02rem, 4vw, 1.26rem);
  font-weight: 950;
  line-height: 1.05;
}

.season-select-button em {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  padding: 0 12px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--lime) 26%, #dffff0);
  color: var(--field);
  font-size: 0.82rem;
  font-style: normal;
  font-weight: 950;
}

.season-select-button b {
  justify-self: end;
  color: #041612;
  font-size: 1.6rem;
  line-height: 1;
}

.season-select-help {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #738186;
  font-size: 0.88rem;
  font-weight: 750;
}

.season-select-help::before {
  content: "i";
  width: 18px;
  height: 18px;
  display: inline-grid;
  place-items: center;
  border: 1.5px solid currentColor;
  border-radius: 50%;
  font-family: Georgia, serif;
  font-style: italic;
  font-weight: 950;
}

.category-options {
  display: grid;
  gap: 10px;
}

.category-option {
  position: relative;
  width: 100%;
  min-height: 92px;
  display: grid;
  grid-template-columns: 54px minmax(0, 1fr) 26px;
  gap: 12px;
  align-items: center;
  padding: 14px;
  border: 1.5px solid #b8cbc5;
  border-radius: 8px;
  background:
    radial-gradient(circle at 100% 0%, rgba(140, 247, 76, 0.12), transparent 36%),
    #ffffff;
  color: var(--field-dark);
  text-align: left;
  box-shadow: 0 10px 22px rgba(1, 20, 17, 0.05);
  transition: transform 160ms ease, box-shadow 160ms ease, border-color 160ms ease, background 160ms ease;
}

.category-option.selected {
  min-height: 102px;
  grid-template-columns: 54px minmax(0, 1fr) 50px;
  border-color: #8cff45;
  background:
    radial-gradient(circle at 96% 12%, rgba(167, 255, 33, 0.46), transparent 24%),
    linear-gradient(110deg, #1458d8 0%, #078f85 48%, #22d861 76%, #9aff2f 100%);
  color: #fff;
  box-shadow: 0 16px 34px rgba(5, 126, 89, 0.28), 0 0 0 1px rgba(140, 247, 76, 0.38);
}

.category-option-icon {
  width: 52px;
  height: 52px;
  display: grid;
  place-items: center;
  border: 2px solid currentColor;
  border-radius: 14px 14px 18px 18px;
  color: var(--field);
  font-size: 0.82rem;
  font-weight: 1000;
  line-height: 1;
}

.category-option.selected .category-option-icon {
  color: #fff;
}

.category-option-copy {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.category-option-copy strong {
  min-width: 0;
  overflow-wrap: anywhere;
  color: currentColor;
  font-size: clamp(1.05rem, 4vw, 1.3rem);
  font-weight: 1000;
  line-height: 1.06;
  text-transform: uppercase;
}

.category-option-copy small {
  min-width: 0;
  overflow-wrap: anywhere;
  color: color-mix(in srgb, currentColor 76%, #34454a);
  font-size: clamp(0.84rem, 3.3vw, 0.98rem);
  font-weight: 800;
  line-height: 1.25;
}

.category-option.selected .category-option-copy small {
  color: color-mix(in srgb, #d7ff5a 74%, #fff);
}

.category-option-copy em {
  width: fit-content;
  max-width: 100%;
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px dashed #cddbd5;
  color: var(--field);
  font-size: 0.86rem;
  font-style: normal;
  font-weight: 950;
}

.category-option-action {
  justify-self: end;
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: #061612;
  font-size: 2rem;
  font-weight: 700;
  line-height: 1;
}

.category-option.selected .category-option-action {
  background: #fff;
  color: var(--field);
  font-size: 1.3rem;
  font-weight: 1000;
}

.category-option-state {
  grid-column: 2 / 4;
  justify-self: end;
  color: #d7ff5a;
  font-size: 0.72rem;
  font-weight: 1000;
  text-transform: uppercase;
}

.category-show-all-button {
  width: 100%;
  min-height: 54px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 0 16px;
  border: 1.5px dashed color-mix(in srgb, var(--field) 44%, #aabbb5);
  border-radius: 8px;
  background: color-mix(in srgb, var(--lime) 10%, #fff);
  color: var(--field);
  font-weight: 950;
}

.category-show-all-button b {
  font-size: 1.8rem;
  line-height: 1;
}

.current-tournament-summary {
  position: relative;
  z-index: 1;
  min-height: 56px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  border-radius: 8px;
  background:
    radial-gradient(circle at 100% 0%, rgba(140, 247, 76, 0.14), transparent 30%),
    linear-gradient(90deg, #eefbf6, #f7fffb);
  color: #34454a;
}

.current-tournament-summary > span {
  width: 26px;
  height: 26px;
  flex: 0 0 auto;
  border: 2px solid var(--field);
  border-radius: 50%;
}

.current-tournament-summary > span::before,
.current-tournament-summary > span::after {
  content: "";
  display: block;
  background: var(--field);
}

.current-tournament-summary > span::before {
  width: 8px;
  height: 8px;
  margin: 7px auto 0;
  border-radius: 50%;
}

.current-tournament-summary > span::after {
  width: 2px;
  height: 8px;
  margin: -1px auto 0;
}

.current-tournament-summary p {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin: 0;
  font-weight: 850;
  line-height: 1.2;
}

.current-tournament-summary strong {
  color: var(--field);
  font-weight: 1000;
}

.tournament-selector-sheet-backdrop {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: grid;
  align-items: end;
  padding: 0;
  background: rgba(2, 8, 6, 0.56);
  backdrop-filter: blur(8px);
}

.tournament-selector-sheet {
  width: min(100%, 560px);
  max-height: min(86svh, 720px);
  justify-self: center;
  display: grid;
  gap: 14px;
  overflow: auto;
  padding: 16px;
  border-radius: 8px 8px 0 0;
  background: #f8fffb;
  box-shadow: 0 -24px 60px rgba(2, 8, 6, 0.28);
}

.tournament-selector-sheet-head {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 12px;
}

.tournament-selector-sheet-head div {
  min-width: 0;
  display: grid;
  gap: 4px;
}

.tournament-selector-sheet-head span {
  color: var(--field);
  font-size: 0.72rem;
  font-weight: 950;
  text-transform: uppercase;
}

.tournament-selector-sheet-head strong {
  color: #071816;
  font-size: 1.25rem;
  line-height: 1.05;
}

.tournament-selector-sheet-head button {
  width: 40px;
  height: 40px;
  flex: 0 0 auto;
  padding: 0;
  border: 1px solid #c8d9d2;
  border-radius: 50%;
  background: #fff;
  color: var(--field-dark);
  font-size: 1.45rem;
}

.tournament-sheet-search {
  display: grid;
  gap: 6px;
}

.tournament-sheet-search span {
  color: var(--muted);
  font-size: 0.76rem;
  font-weight: 950;
  text-transform: uppercase;
}

.tournament-sheet-search input {
  min-height: 46px;
  border: 1px solid #c8d9d2;
  border-radius: 8px;
  background: #fff;
}

.tournament-sheet-list.clean,
.tournament-sheet-list.compact {
  display: grid;
  gap: 10px;
}

.tournament-sheet-list.clean button,
.tournament-sheet-list.compact button {
  width: 100%;
  min-height: 64px;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 10px;
  border: 1px solid #c8d9d2;
  border-radius: 8px;
  background: #fff;
  color: var(--field-dark);
  text-align: left;
}

.tournament-sheet-list.clean button.active,
.tournament-sheet-list.compact button.active {
  border-color: #8cff45;
  background: linear-gradient(90deg, color-mix(in srgb, var(--lime) 18%, #fff), #fff);
  box-shadow: 0 10px 24px rgba(30, 185, 101, 0.12);
}

.sheet-season-icon {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  background: #e7fbf1;
  color: var(--field);
  font-size: 1.1rem;
}

.tournament-sheet-list.clean span:not(.sheet-season-icon),
.tournament-sheet-list.compact span:not(.competition-mark) {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.tournament-sheet-list.clean strong,
.tournament-sheet-list.compact strong {
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--field-dark);
  font-size: 0.98rem;
  font-weight: 950;
  line-height: 1.08;
}

.tournament-sheet-list.clean small,
.tournament-sheet-list.compact small {
  color: var(--muted);
  font-size: 0.74rem;
  font-weight: 850;
}

.tournament-sheet-list.clean em,
.tournament-sheet-list.compact em {
  color: var(--field);
  font-size: 0.8rem;
  font-style: normal;
  font-weight: 950;
  text-align: right;
  text-transform: uppercase;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  clip-path: inset(50%);
}

@media (min-width: 760px) {
  .tournament-selector-layout {
    grid-template-columns: minmax(260px, 0.68fr) minmax(0, 1fr);
    align-items: start;
  }

  .category-select-block {
    padding-left: 18px;
    border-left: 1px solid #dbe8e2;
  }

  .category-options {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .category-option.selected {
    grid-column: span 2;
  }

  .current-tournament-summary {
    max-width: 720px;
  }

  .tournament-selector-sheet-backdrop {
    align-items: center;
    padding: 24px;
  }

  .tournament-selector-sheet {
    border-radius: 8px;
  }
}

@media (max-width: 480px) {
  .tournament-selector {
    padding: 16px 12px;
  }

  .tournament-selector::after {
    top: 52px;
    right: 12px;
    width: 82px;
    height: 82px;
    border-width: 7px;
  }

  .season-select-button {
    grid-template-columns: 34px minmax(0, 1fr) auto 22px;
    gap: 9px;
    min-height: 60px;
    padding: 9px 10px;
  }

  .season-select-icon {
    width: 30px;
    height: 30px;
    border-top-width: 5px;
  }

  .season-select-button em {
    min-height: 28px;
    padding: 0 9px;
    font-size: 0.74rem;
  }

  .category-option,
  .category-option.selected {
    grid-template-columns: 46px minmax(0, 1fr) 34px;
    gap: 10px;
    min-height: 88px;
    padding: 12px 10px;
  }

  .category-option-icon {
    width: 44px;
    height: 44px;
    font-size: 0.72rem;
  }

  .category-option-action {
    width: 32px;
    height: 32px;
    font-size: 1.7rem;
  }

  .category-option-state {
    font-size: 0.66rem;
  }

  .current-tournament-summary {
    align-items: start;
    padding: 10px 12px;
  }

  .current-tournament-summary p {
    gap: 6px;
    font-size: 0.9rem;
  }
}

.playoff-list {
  display: grid;
  gap: 10px;
}

.playoff-phase-group {
  display: grid;
  gap: 8px;
}

.playoff-round-summary {
  margin: 0;
}

.playoff-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(110px, auto);
  gap: 12px;
  align-items: center;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fbfdfb;
}

.playoff-card span,
.playoff-card small,
.playoff-score span {
  color: var(--muted);
  font-weight: 800;
}

.playoff-card strong,
.playoff-card small,
.playoff-card span {
  display: block;
}

.playoff-score {
  text-align: right;
}

.playoff-score strong {
  font-size: 1.25rem;
}

.playoff-score span:nth-child(n + 3) {
  color: var(--field-dark);
  font-size: 0.78rem;
}

.match-list {
  display: grid;
  gap: 8px;
}

.match-card {
  border: 1px solid color-mix(in srgb, var(--field) 18%, var(--line));
  border-left: 4px solid var(--field);
  border-radius: 8px;
  background: linear-gradient(135deg, #ffffff, #fbfdfb 72%, color-mix(in srgb, var(--lime) 10%, #fff));
  box-shadow: 0 8px 22px rgba(23, 33, 28, 0.07);
  overflow: hidden;
}

.match-card summary {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 12px;
  align-items: center;
  min-height: 70px;
  padding: 12px;
  cursor: pointer;
  list-style: none;
}

.match-card summary::-webkit-details-marker {
  display: none;
}

.match-card summary::after {
  content: "+";
  width: 26px;
  height: 26px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--field);
  font-weight: 950;
}

.match-card[open] summary::after {
  content: "-";
}

.match-card summary > strong {
  min-width: 84px;
  text-align: right;
  white-space: nowrap;
  color: var(--field-dark);
  font-weight: 950;
}

.match-card-main {
  display: grid;
  gap: 7px;
  min-width: 0;
}

.match-card-kicker {
