  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
}

.match-card-kicker span,
.match-card-place {
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 950;
  text-transform: uppercase;
}

.match-card-kicker span:first-child {
  min-height: 24px;
  display: inline-flex;
  align-items: center;
  border-radius: 8px;
