  padding: 0 8px;
}

.match-card-place {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.match-card-result {
  display: grid;
  gap: 6px;
  justify-items: end;
  min-width: 92px;
}

.match-card-result > strong {
  color: var(--field-dark);
  font-size: 1rem;
  font-weight: 950;
  line-height: 1;
  text-align: right;
  white-space: nowrap;
}

.match-details {
  display: grid;
  gap: 12px;
  padding: 12px;
  border-top: 1px solid var(--line);
  background: #101819;
  color: #f8fafc;
}

.match-expanded-head {
  display: grid;
  gap: 4px;
  justify-items: center;
  text-align: center;
}

.match-expanded-head span,
.match-expanded-head small {
  color: #a8b2ad;
  font-weight: 850;
  text-transform: uppercase;
}

.match-expanded-head strong {
  color: #fff;
  font-size: 1rem;
}

.match-scoreboard {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(72px, auto) minmax(0, 1fr);
