  gap: 3px;
  justify-items: center;
  text-align: center;
}

.match-score-center span,
.match-score-center small {
  color: #a8b2ad;
  font-size: 0.76rem;
  font-weight: 900;
  text-transform: uppercase;
}

.match-score-center strong {
