  background: #1f2a2d;
  color: #fff;
  font-size: 0.72rem;
  font-weight: 1000;
}

.match-timeline-card {
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr);
  gap: 7px;
  align-items: center;
  min-width: 0;
  padding: 6px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.07);
}

.match-timeline-icon {
  display: inline-grid;
  place-items: center;
  width: 22px;
  height: 22px;
  font-size: 0.78rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.12);
  line-height: 1;
}

.match-timeline-card strong,
.match-timeline-card small {
  display: block;
  min-width: 0;
  overflow-wrap: anywhere;
}

.match-timeline-card strong {
  color: #fff;
  font-size: 0.72rem;
  line-height: 1.15;
}

.match-timeline-card small {
  color: #2ae7bc;
  font-size: 0.62rem;
  font-weight: 850;
}

.match-timeline-half {
  position: relative;
  z-index: 1;
  display: inline-flex;
  grid-column: 1 / -1;
  justify-self: center;
  align-items: center;
  gap: 8px;
  min-height: 30px;
  padding: 0 12px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 999px;
  background: #1f2a2d;
  color: #dbe6e0;
  font-size: 0.68rem;
  font-weight: 950;
  text-transform: uppercase;
}

.match-timeline-half.phase-extra_time {
