}

.match-timeline-note {
  color: #a8b2ad;
  font-size: 0.68rem;
  font-weight: 850;
  text-align: center;
}

.match-events-divider {
  display: grid;
  justify-items: center;
  padding-top: 34px;
}

.match-events-divider span {
  width: 1px;
