  font-size: 0.82rem;
  font-weight: 800;
  text-align: center;
}

.match-event-row {
  display: grid;
  grid-template-columns: 36px 34px minmax(0, 1fr);
  gap: 6px;
  align-items: center;
  min-height: 38px;
  padding: 7px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.045);
}

.match-event-row.without-minute {
  grid-template-columns: 34px minmax(0, 1fr);
}

.match-event-minute {
  color: #dbe6e0;
  font-weight: 950;
  text-align: right;
}

.match-event-badge {
  min-height: 24px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: #e2e8f0;
  color: #0f172a;
  font-size: 0.76rem;
  font-weight: 950;
}

.match-event-row.yellow .match-event-badge {
  background: #facc15;
  color: #422006;
}

.match-event-row.red .match-event-badge {
  background: #ef4444;
  color: #fff;
}

.match-event-row.own_goal .match-event-badge {
  background: #38bdf8;
  color: #082f49;
}

.match-event-row div {
  min-width: 0;
}

.match-event-row div strong,
.match-event-row div small {
  display: block;
  overflow-wrap: anywhere;
}

.match-event-row div strong {
  color: #fff;
  font-size: 0.78rem;
  line-height: 1.15;
}

.match-event-row div small {
  color: #9aa6a0;
  font-size: 0.66rem;
  font-weight: 800;
}

.match-events-empty {
  display: grid;
  gap: 6px;
  justify-items: center;
  padding: 14px;
  border: 1px dashed rgba(255, 255, 255, 0.16);
  border-radius: 8px;
}

.match-events-empty strong {
  color: #fff;
}

.match-details p {
  margin: 0;
}

.match-observations {
  display: grid;
  gap: 4px;
  padding: 10px 12px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.06);
  color: #dbe6e0;
  font-weight: 800;
}

.match-observations strong {
  color: #fff;
  font-size: 0.78rem;
  text-transform: uppercase;
}

.rest-card {
  display: grid;
  grid-template-columns: 180px minmax(0, 1fr);
  gap: 16px;
  align-items: center;
  padding: 14px;
  border: 1px dashed color-mix(in srgb, var(--field) 35%, var(--line));
  border-radius: 8px;
  background: color-mix(in srgb, var(--lime) 10%, #fff);
}

.rest-card span {
  color: var(--muted);
  font-size: 0.8rem;
  font-weight: 900;
  text-transform: uppercase;
}

.rest-card strong {
  overflow-wrap: anywhere;
}

.spotlight-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 210px), 1fr));
  gap: 12px;
  margin: 20px 0;
}

.spotlight-strip article {
  position: relative;
  min-width: 0;
  padding: 16px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--field) 18%, var(--line));
  border-radius: 8px;
  background:
    linear-gradient(135deg, #fff, #fbfdfb 72%, color-mix(in srgb, var(--lime) 13%, #fff));
  box-shadow: 0 10px 28px rgba(23, 33, 28, 0.08);
}

.spotlight-strip article::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
