}

.spotlight-strip span,
.spotlight-strip small {
  display: block;
  color: var(--muted);
  font-weight: 800;
}

.spotlight-strip span {
  font-size: 0.78rem;
  text-transform: uppercase;
}

.spotlight-strip strong {
