  align-items: center;
  justify-content: center;
  margin: 0 16px 16px;
  border-radius: 8px;
  background: color-mix(in srgb, var(--lime) 72%, #fff);
  color: #0f2f24;
  font-weight: 950;
  text-decoration: none;
  text-transform: uppercase;
}

.ad-slot {
  position: relative;
  min-height: 220px;
  display: grid;
  gap: 14px;
  overflow: hidden;
  padding: 16px;
  border: 1px solid color-mix(in srgb, var(--field) 28%, rgba(255, 255, 255, 0.18));
  border-radius: 8px;
  color: #fff;
  background:
    radial-gradient(circle at 14% 0%, color-mix(in srgb, var(--blue) 38%, transparent), transparent 34%),
    radial-gradient(circle at 92% 12%, color-mix(in srgb, var(--lime) 30%, transparent), transparent 28%),
    linear-gradient(145deg, color-mix(in srgb, var(--field-dark) 94%, #020617), #07130f 58%, color-mix(in srgb, var(--field) 76%, #020617));
  box-shadow:
    0 18px 44px rgba(2, 6, 23, 0.18),
    inset 0 1px 0 rgba(255, 255, 255, 0.14);
}

.ad-slot::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(90deg, rgba(255,255,255,0.08), transparent 18%, transparent 78%, rgba(255,255,255,0.06)),
    repeating-linear-gradient(135deg, rgba(255,255,255,0.055) 0 1px, transparent 1px 14px);
  mix-blend-mode: screen;
}

.ad-slot::after {
  content: "";
  position: absolute;
  inset: auto 18px 12px;
  height: 1px;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--lime) 65%, #fff), transparent);
  opacity: 0.7;
}

.ad-slot > * {
  position: relative;
  z-index: 1;
}

.ad-slot-head {
  display: grid;
  gap: 5px;
}

.ad-slot-head span {
  width: fit-content;
  max-width: 100%;
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 10px;
  border: 1px solid rgba(255,255,255,0.14);
  border-radius: 999px;
  background: rgba(255,255,255,0.1);
  color: color-mix(in srgb, var(--lime) 76%, #fff);
  font-size: 0.68rem;
  font-weight: 950;
  text-transform: uppercase;
}

.ad-slot-head strong {
  max-width: 18ch;
  color: #fff;
  font-size: clamp(1.18rem, 2.4vw, 1.58rem);
  line-height: 1.02;
  text-wrap: balance;
  text-transform: uppercase;
}

.sponsor-public-strip {
  display: grid;
  max-height: 390px;
  overflow: hidden;
  border-radius: 8px;
  -webkit-mask-image: linear-gradient(180deg, transparent, #000 8%, #000 92%, transparent);
  mask-image: linear-gradient(180deg, transparent, #000 8%, #000 92%, transparent);
}

.sponsor-public-track {
  display: grid;
  gap: 12px;
  padding: 2px;
}

.sponsor-public-strip.is-carousel .sponsor-public-track {
  animation: sponsor-slide 18s linear infinite;
}

.sponsor-public-strip.is-carousel:hover .sponsor-public-track {
  animation-play-state: paused;
}

.sponsor-public-strip a,
.sponsor-public-strip article {
  position: relative;
  display: grid;
  gap: 8px;
  overflow: hidden;
  padding: 8px;
  border: 1px solid rgba(255,255,255,0.16);
  border-radius: 8px;
  background:
    linear-gradient(145deg, rgba(255,255,255,0.18), rgba(255,255,255,0.08)),
    rgba(255,255,255,0.1);
  color: #fff;
  box-shadow:
    0 14px 26px rgba(0, 0, 0, 0.14),
    inset 0 1px 0 rgba(255, 255, 255, 0.22);
  text-decoration: none;
  transition: transform 180ms ease, border-color 180ms ease, background-color 180ms ease;
}

.sponsor-public-strip a::after,
.sponsor-public-strip article::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(115deg, transparent 0 42%, rgba(255,255,255,0.18) 50%, transparent 58% 100%);
  opacity: 0;
  transform: translateX(-28%);
  transition: opacity 180ms ease, transform 360ms ease;
}

.sponsor-public-strip a:hover,
.sponsor-public-strip article:hover {
  border-color: color-mix(in srgb, var(--lime) 54%, rgba(255,255,255,0.18));
  background: rgba(255,255,255,0.16);
  transform: translateY(-2px);
}

.sponsor-public-strip a:hover::after,
.sponsor-public-strip article:hover::after {
  opacity: 1;
  transform: translateX(28%);
}

.sponsor-image-frame {
