  font-size: 0.9rem;
  font-weight: 800;
}

@keyframes public-rise-in {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes public-loader-out {
  0%,
  62% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    visibility: hidden;
  }
}

@keyframes public-score-pulse {
  0%,
  100% {
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.12);
  }
  50% {
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--lime) 50%, #fff);
  }
}

@keyframes sponsor-slide {
  from {
    transform: translateY(0);
  }
  to {
    transform: translateY(-50%);
  }
}

.public-hero .hero-content,
.hero-match-panel,
.public-pulse-bar article,
.stats-grid article,
.spotlight-strip article,
.competition-panel,
.content-grid > * {
  animation: public-rise-in 520ms ease both;
}

.hero-match-panel {
  animation-delay: 90ms;
}

.stats-grid article:nth-child(2),
.spotlight-strip article:nth-child(2) {
  animation-delay: 70ms;
}

.stats-grid article:nth-child(3),
.spotlight-strip article:nth-child(3) {
  animation-delay: 120ms;
}

.stats-grid article:nth-child(4),
.spotlight-strip article:nth-child(4) {
  animation-delay: 170ms;
}

.hero-match-score {
  animation: public-score-pulse 3.8s ease-in-out infinite;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

