  border: 1px solid color-mix(in srgb, var(--field) 18%, var(--line));
  background: color-mix(in srgb, var(--field) 8%, #fff);
  color: var(--field-dark) !important;
  font-size: 0.72rem;
  font-weight: 950;
  text-transform: uppercase;
}

.match-touch-hint svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.8;
}

.match-card-footer .status {
  display: inline-flex !important;
}

.match-card {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(43, 255, 135, 0.2);
  border-left: 0;
  border-radius: 8px;
  background:
    radial-gradient(circle at 26% 46%, rgba(47, 255, 135, 0.16), transparent 34%),
    radial-gradient(circle at 78% 0%, rgba(140, 247, 76, 0.11), transparent 30%),
    linear-gradient(135deg, rgba(2, 11, 19, 0.97), rgba(5, 27, 31, 0.95) 56%, rgba(4, 36, 21, 0.9));
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.18), inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.match-card.is-scheduled {
  border-color: rgba(76, 182, 255, 0.22);
  background:
    radial-gradient(circle at 26% 46%, rgba(47, 166, 255, 0.14), transparent 34%),
    linear-gradient(135deg, rgba(2, 11, 19, 0.98), rgba(4, 23, 34, 0.95) 58%, rgba(6, 15, 24, 0.94));
}

.match-card.is-search-focused {
  border-color: rgba(56, 189, 248, 0.98);
  animation: matchSearchTone 1250ms ease-in-out infinite;
  box-shadow:
    0 0 0 5px rgba(56, 189, 248, 0.42),
    0 20px 50px rgba(14, 165, 233, 0.4),
    inset 0 0 42px rgba(56, 189, 248, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.12);
}

.match-card.is-search-focused::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 2;
  background:
    radial-gradient(circle at 50% 50%, rgba(56, 189, 248, 0.44), transparent 58%),
    linear-gradient(90deg, rgba(8, 39, 57, 0.36), rgba(56, 189, 248, 0.26));
  opacity: 0.68;
  pointer-events: none;
  animation: matchSearchWash 1250ms ease-in-out infinite;
}

@keyframes matchSearchTone {
  0%,
  100% {
    box-shadow:
      0 0 0 4px rgba(56, 189, 248, 0.32),
      0 18px 42px rgba(14, 165, 233, 0.3),
      inset 0 0 32px rgba(56, 189, 248, 0.16),
      inset 0 1px 0 rgba(255, 255, 255, 0.1);
  }

  50% {
    box-shadow:
      0 0 0 10px rgba(56, 189, 248, 0.62),
      0 26px 62px rgba(14, 165, 233, 0.48),
      inset 0 0 58px rgba(56, 189, 248, 0.34),
      inset 0 1px 0 rgba(255, 255, 255, 0.18);
  }
}

@keyframes matchSearchWash {
  0%,
  100% {
    opacity: 0.46;
  }

  50% {
    opacity: 0.9;
  }
}

.match-card summary,
.match-card-face {
  position: relative;
  display: grid;
  align-items: center;
  grid-template-columns: minmax(92px, 132px) minmax(0, 1fr) minmax(84px, 118px);
  gap: 0;
  min-height: 112px;
  padding: 0;
  overflow: hidden;
  cursor: default;
  list-style: none;
}

.match-card summary::after {
  display: none;
}

.match-card-date {
  align-self: stretch;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 4px;
  min-width: 0;
  padding: 9px 14px 9px 10px;
  clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 50%, calc(100% - 18px) 100%, 0 100%);
