  display: grid;
  align-content: center;
  min-width: 0;
  padding: 24px 10px 12px;
}

.match-card-kicker {
  position: absolute;
  top: 0;
  left: 50%;
  z-index: 1;
  display: inline-flex;
  justify-content: center;
  max-width: min(84%, 260px);
  transform: translateX(-50%);
}

.match-card-kicker span {
  min-height: 24px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  max-width: 100%;
