}

.match-card-action[data-match-detail-trigger="true"] {
  align-self: center;
  min-height: 74px;
  margin: 10px 10px 10px 0;
  border: 1px solid rgba(154, 255, 88, 0.42);
  border-radius: 12px;
  background:
    radial-gradient(circle at 18% 0%, rgba(184, 255, 118, 0.24), transparent 34%),
    linear-gradient(135deg, rgba(10, 54, 34, 0.96), rgba(11, 115, 66, 0.86));
  box-shadow:
    0 12px 24px rgba(43, 255, 135, 0.14),
    inset 0 1px 0 rgba(255, 255, 255, 0.16);
  cursor: pointer;
  transition: transform 160ms ease, border-color 160ms ease, box-shadow 160ms ease, filter 160ms ease;
}

.match-card-action[data-match-detail-trigger="true"]:hover,
.match-card-action[data-match-detail-trigger="true"]:focus-visible {
  border-color: rgba(184, 255, 118, 0.82);
  box-shadow:
    0 15px 28px rgba(43, 255, 135, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.2);
  filter: saturate(1.08);
  transform: translateY(-1px);
  outline: none;
}

.match-card-action[data-match-detail-trigger="true"]:active {
  transform: translateY(0);
}

.match-card-action[data-match-detail-trigger="true"] span {
  color: rgba(236, 255, 246, 0.72);
}

.match-card-mobile-meta {
  display: none;
}

.match-card-meta-icon {
  color: currentColor;
}

@media (max-width: 430px) {
  .match-card summary,
  .match-card-face {
    grid-template-columns: 72px minmax(0, 1fr);
    min-height: 102px;
  }

  .match-card-action {
    display: none;
  }

  .match-card-mobile-meta {
    grid-column: 1 / -1;
    display: grid;
    grid-template-columns: minmax(0, 0.8fr) minmax(0, 1.2fr);
    gap: 6px;
    padding: 0 8px 7px;
  }

  .match-card-mobile-meta span {
    min-width: 0;
    min-height: 30px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 5px;
    padding: 0 7px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.055);
    color: rgba(232, 246, 242, 0.74);
    font-size: 0.56rem;
    font-weight: 950;
    text-align: center;
    text-transform: uppercase;
  }

  .match-card-mobile-meta .match-touch-hint {
    border-color: rgba(154, 255, 88, 0.48);
    background:
      radial-gradient(circle at 18% 0%, rgba(184, 255, 118, 0.22), transparent 36%),
