    color: #eaffc8 !important;
    box-shadow:
      0 10px 20px rgba(43, 255, 135, 0.15),
      inset 0 1px 0 rgba(255, 255, 255, 0.16);
    cursor: pointer;
    transition: transform 160ms ease, border-color 160ms ease, box-shadow 160ms ease;
  }

  .match-card-mobile-meta .match-touch-hint:hover,
  .match-card-mobile-meta .match-touch-hint:focus-visible {
    border-color: rgba(184, 255, 118, 0.84);
    box-shadow:
      0 12px 24px rgba(43, 255, 135, 0.2),
      inset 0 1px 0 rgba(255, 255, 255, 0.2);
    transform: translateY(-1px);
    outline: none;
  }

  .match-card-mobile-meta .match-touch-hint:active {
    transform: translateY(0);
  }

  .match-card-mobile-meta .match-card-meta-icon {
    width: 14px;
    height: 14px;
  }
}

@media (max-width: 430px) {
  .public-league-page .match-card-mobile-meta {
