}

.delegate-summary-cards strong {
  display: block;
  color: #087557;
  font-size: 1.42rem;
}

.delegate-wizard-card {
  grid-template-columns: 1fr;
  gap: 14px;
  margin: 0;
  padding: 16px;
  border: 1px solid #dcebe5;
  border-radius: 8px;
  background: #fff;
  box-shadow: 0 14px 34px rgba(10, 47, 38, 0.06);
}

.delegate-wizard-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(220px, 0.9fr);
  gap: 14px;
  align-items: center;
}

.delegate-wizard-head h3 {
  color: #061a16;
  font-size: 1.22rem;
}

.delegate-stepper {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.delegate-stepper span {
  min-width: 0;
