  justify-items: center;
  gap: 5px;
  color: #81908b;
  font-size: 0.78rem;
  font-weight: 950;
}

.delegate-stepper span::before {
  content: attr(class);
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #edf2f0;
}

.delegate-stepper span:nth-child(1)::before { content: "1"; }
.delegate-stepper span:nth-child(2)::before { content: "2"; }
.delegate-stepper span:nth-child(3)::before { content: "3"; }

.delegate-stepper span.active::before {
  background: linear-gradient(135deg, #087557, #20d58e);
  color: #fff;
}

.delegate-stepper b {
  color: inherit;
  font-size: 0.62rem;
}

.delegate-wizard-card fieldset {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin: 0;
  padding: 14px;
  border: 1px solid #e0ebe7;
  border-radius: 8px;
  background: #fbfdfc;
}

.delegate-wizard-card fieldset:nth-of-type(2) {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.delegate-wizard-card legend {
  padding: 0 8px;
  color: #087557;
  font-size: 0.78rem;
  font-weight: 950;
  text-transform: uppercase;
}

.delegate-form-note {
  margin: 0;
  padding: 11px 12px;
  border: 1px solid #c9eadb;
  border-radius: 8px;
  background: #effaf4;
  color: #0c6049;
  font-size: 0.82rem;
  font-weight: 850;
}

.delegate-filter-bar {
  border-color: #dcebe5;
  border-radius: 8px;
  background: #fff;
  box-shadow: 0 10px 24px rgba(10, 47, 38, 0.05);
}

.delegate-tabs {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
  padding: 5px;
  border-radius: 8px;
  background: #f1f6f4;
}

.delegate-tabs button {
  min-height: 42px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: #4f625c;
  font-weight: 950;
}

.delegate-tabs button.active,
.delegate-tabs button[aria-selected="true"] {
  background: linear-gradient(135deg, #098261, #056146);
  color: #fff;
  box-shadow: 0 10px 20px rgba(8, 117, 87, 0.18);
}

.delegate-grid {
  grid-template-columns: 1fr;
}

.delegate-list-panel {
  display: grid;
  gap: 10px;
}

.delegate-section-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
}

.delegate-section-head h3 {
  color: #061a16;
}

.delegate-section-head small {
  color: #087557;
  font-weight: 950;
}

.delegate-compact-group,
.delegate-card {
