}

.delegate-user-card > summary {
  grid-template-columns: minmax(0, 1fr) auto;
}

@media (max-width: 760px) {
  .delegate-admin-shell {
    gap: 12px;
  }

  .delegate-admin-hero {
    grid-template-columns: 48px minmax(0, 1fr);
    padding: 14px;
  }

  .delegate-hero-icon {
    width: 48px;
    height: 48px;
  }

  .delegate-hero-action {
    grid-column: 1 / -1;
    width: 100%;
  }

  .delegate-quick-actions {
    grid-template-columns: 1fr;
  }

  .delegate-quick-actions a,
  .delegate-quick-actions button {
    min-height: 68px;
  }

  .delegate-summary-cards {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .delegate-wizard-card {
    padding: 12px;
  }

  .delegate-wizard-head {
    grid-template-columns: 1fr;
  }

  .delegate-wizard-card fieldset,
  .delegate-wizard-card fieldset:nth-of-type(2) {
    grid-template-columns: 1fr;
    padding: 12px;
  }

  .delegate-stepper {
    gap: 4px;
  }

  .delegate-stepper span::before {
    width: 28px;
    height: 28px;
  }

  .delegate-filter-bar {
    grid-template-columns: 1fr;
    margin: 0;
  }

  .delegate-tabs {
    position: sticky;
    top: 0;
    z-index: 3;
  }

  .delegate-section-head {
    align-items: flex-start;
  }
}

