.referee-status {
  width: fit-content;
  padding: 7px 10px;
  border-radius: 999px;
  font-size: 0.7rem;
  font-weight: 950;
  text-transform: uppercase;
}

.referee-status.ready,
.referee-status.done {
  background: rgba(140, 247, 76, 0.16);
  color: #b7ff74;
}

.referee-status.review {
  background: rgba(10, 132, 255, 0.2);
  color: #82c7ff;
}

.referee-status.rejected {
  background: rgba(255, 198, 77, 0.18);
  color: #ffd982;
}

.referee-status.readonly {
  background: rgba(234, 248, 245, 0.12);
  color: rgba(234, 248, 245, 0.74);
}

.delegate-schedule-note,
.match-schedule-note {
  display: block;
  margin: 0;
  padding: 8px 10px;
  border: 1px solid rgba(244, 197, 33, 0.26);
  border-radius: 10px;
  color: #ffe07a;
  background: rgba(244, 197, 33, 0.07);
  font-size: 0.68rem;
  font-weight: 900;
  line-height: 1.25;
}

.match-card.is-postponed {
  border-color: rgba(239, 63, 69, 0.26);
}

.referee-match-main {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  gap: 10px;
  align-items: center;
}

.referee-match-main > div:not(.referee-match-score) {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.referee-match-main > div:last-child {
  text-align: right;
}

.referee-match-main strong {
  color: #fff;
  overflow-wrap: anywhere;
}

.referee-match-score {
  display: grid;
  min-width: 62px;
  min-height: 42px;
  place-items: center;
  padding: 8px 10px;
  border: 1px solid rgba(140, 247, 76, 0.28);
  border-radius: 8px;
  background: linear-gradient(135deg, rgba(10, 132, 255, 0.22), rgba(42, 231, 188, 0.13));
  color: #fff;
  font-size: 1.1rem;
  font-weight: 950;
}

.referee-match-meta span {
  padding: 6px 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
}

.referee-card-note {
  margin: 0;
  color: rgba(234, 248, 245, 0.76);
  font-size: 0.82rem;
  font-weight: 800;
}

.referee-action-button {
  justify-self: start;
  min-height: 46px;
  padding: 12px 16px;
  border: 1px solid rgba(42, 231, 188, 0.24);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
  font-weight: 950;
}

.referee-action-button.primary-action {
  border: 0;
  background: linear-gradient(135deg, #0877ff, #22e7bc 58%, #8cf74c);
  color: #03111b;
  box-shadow: 0 12px 28px rgba(34, 231, 188, 0.22);
}

.referee-action-button.warning {
  border: 0;
  background: linear-gradient(135deg, #ffc64d, #8cf74c);
  color: #251b05;
}

.referee-capture-wrap {
  display: grid;
  gap: 10px;
  min-width: 0;
}

.referee-sheet-form {
  display: grid;
  gap: 16px;
  padding: clamp(12px, 2.8vw, 18px);
  border: 1px solid rgba(140, 247, 76, 0.26);
  border-radius: 12px;
  background:
    radial-gradient(circle at top left, rgba(140, 247, 76, 0.13), transparent 32%),
    radial-gradient(circle at 92% 6%, rgba(8, 119, 255, 0.2), transparent 30%),
    linear-gradient(160deg, rgba(1, 10, 18, 0.98), rgba(3, 24, 35, 0.96) 52%, rgba(5, 49, 41, 0.94));
  box-shadow: 0 22px 55px rgba(0, 0, 0, 0.32);
  min-width: 0;
}

.referee-acta-title {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  padding-bottom: 2px;
}

.referee-acta-title button {
  min-height: 44px;
  padding: 10px 12px;
  border: 1px solid rgba(42, 231, 188, 0.24);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
  font-weight: 950;
}

.referee-acta-brand {
  display: flex !important;
  align-items: center;
  gap: 10px;
  margin-bottom: 3px;
}

.referee-acta-brand img {
  width: clamp(108px, 28vw, 154px);
  height: auto;
  object-fit: contain;
  filter: drop-shadow(0 8px 18px rgba(140, 247, 76, 0.16));
}

.referee-acta-title div {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.referee-acta-title span {
  color: #8cf74c;
  font-size: 0.72rem;
  font-weight: 950;
  text-transform: uppercase;
}

.referee-acta-title strong {
  color: #fff;
  overflow-wrap: anywhere;
}

.referee-acta-title small {
  color: rgba(234, 248, 245, 0.7);
  font-weight: 850;
}

.referee-flow-steps {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.referee-flow-steps span {
  min-height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 7px 8px;
  border: 1px solid rgba(42, 231, 188, 0.16);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.055);
  color: rgba(234, 248, 245, 0.68);
  font-size: 0.68rem;
  font-weight: 950;
  line-height: 1.15;
  text-align: center;
  text-transform: uppercase;
}

.referee-flow-steps span.active {
  border-color: rgba(140, 247, 76, 0.42);
  background: linear-gradient(135deg, rgba(140, 247, 76, 0.18), rgba(42, 231, 188, 0.12));
  color: #b7ff74;
}

.referee-sheet-form label {
  color: rgba(234, 248, 245, 0.78);
  font-weight: 900;
}

.referee-sheet-form .auth-ok {
  color: #8cf74c;
}

.referee-sheet-form .auth-error {
  color: #ff9f7a;
}

.referee-sheet-form .inline-actions button:not(.primary) {
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
}

.referee-sheet-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(96px, auto) minmax(0, 1fr);
  gap: 10px;
  align-items: center;
  text-align: center;
  padding: 12px;
  border: 1px solid rgba(42, 231, 188, 0.18);
  border-radius: 12px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.035)),
    rgba(2, 15, 24, 0.72);
}

.referee-sheet-head > div:not(.referee-score-box) {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.referee-score-team.home {
  text-align: left;
  justify-items: start;
}

.referee-score-team.away {
  text-align: right;
  justify-items: end;
}

.referee-team-mark {
  display: grid;
  width: clamp(42px, 12vw, 58px);
  height: clamp(42px, 12vw, 58px);
  place-items: center;
  border: 1px solid rgba(140, 247, 76, 0.38);
  border-radius: 999px;
  background:
    radial-gradient(circle at 35% 25%, rgba(255, 255, 255, 0.22), transparent 38%),
    linear-gradient(135deg, #0877ff, #22e7bc 58%, #8cf74c);
  color: #03111b;
  font-size: clamp(0.92rem, 3.8vw, 1.16rem);
  font-weight: 1000;
  letter-spacing: 0;
  box-shadow: 0 10px 24px rgba(42, 231, 188, 0.18);
}

.referee-sheet-head span {
  color: rgba(234, 248, 245, 0.7);
  font-size: 0.72rem;
  font-weight: 950;
  text-transform: uppercase;
}

.referee-sheet-head strong {
  color: #fff;
  max-width: 100%;
  font-size: clamp(0.78rem, 3.2vw, 1.05rem);
  line-height: 1.08;
  text-wrap: balance;
  overflow-wrap: anywhere;
  word-break: normal;
}

.referee-score-box {
  display: grid;
  grid-template-columns: 62px auto 62px;
  gap: 6px;
  align-items: center;
  padding: 8px;
  border: 1px solid rgba(140, 247, 76, 0.26);
  border-radius: 12px;
  background: rgba(1, 10, 18, 0.72);
}

.referee-score-box input {
  min-height: 52px;
  border-color: rgba(42, 231, 188, 0.22);
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
  text-align: center;
  font-size: 1.55rem;
  font-weight: 950;
}

.referee-score-box span {
  color: #8cf74c;
  font-size: 1.65rem;
  font-weight: 1000;
}

.referee-sheet-controls {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.referee-live-panel {
  display: grid;
  gap: 12px;
  padding: 14px;
  border: 1px solid rgba(42, 231, 188, 0.28);
  border-radius: 12px;
  background:
    radial-gradient(circle at top left, rgba(140, 247, 76, 0.13), transparent 34%),
    radial-gradient(circle at bottom right, rgba(8, 119, 255, 0.28), transparent 38%),
    linear-gradient(135deg, rgba(3, 17, 27, 0.98), rgba(5, 38, 44, 0.94));
  min-width: 0;
}

.referee-live-panel.is-active {
  border-color: rgba(140, 247, 76, 0.38);
  box-shadow: 0 14px 36px rgba(8, 119, 255, 0.18);
}

.referee-low-power {
  background: #020406;
  box-shadow: none;
}

.referee-low-power .referee-live-panel,
.referee-low-power .referee-sheet-head,
.referee-low-power .referee-event-row,
.referee-low-power .referee-advanced-panel {
  background: #050809;
  box-shadow: none;
}

.referee-live-mode-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  min-width: 0;
  padding: 10px;
  border: 1px solid rgba(140, 247, 76, 0.24);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.06);
}

.referee-live-mode-card div {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.referee-live-mode-card span,
.referee-live-status-grid span {
  color: #8cf74c;
  font-size: 0.7rem;
  font-weight: 950;
  text-transform: uppercase;
}

.referee-live-mode-card strong {
  color: #fff;
  overflow-wrap: anywhere;
}

.referee-live-mode-card small,
.referee-low-power-toggle small {
  color: rgba(234, 248, 245, 0.7);
  font-weight: 800;
}

.referee-live-mode-card button {
  min-height: 44px;
  padding: 8px 10px;
  border-radius: 8px;
  white-space: normal;
}

.referee-live-status-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
}

.referee-live-status-grid span {
  min-width: 0;
  min-height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 6px 7px;
  border: 1px solid rgba(42, 231, 188, 0.16);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.06);
  color: rgba(234, 248, 245, 0.78);
  line-height: 1.15;
  text-align: center;
}

.referee-live-status-grid span.online {
  border-color: rgba(140, 247, 76, 0.3);
  color: #8cf74c;
}

.referee-live-status-grid span.offline {
  border-color: rgba(246, 196, 83, 0.34);
  color: #f6c453;
}

.referee-live-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  min-width: 0;
}

.referee-live-head > div:first-child {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.referee-live-head span,
.referee-live-added span {
  color: #8cf74c;
  font-size: 0.72rem;
  font-weight: 950;
  text-transform: uppercase;
}

.referee-live-head strong {
  color: #fff;
  overflow-wrap: anywhere;
}

.referee-live-head small {
  color: rgba(234, 248, 245, 0.7);
  font-weight: 850;
}

.referee-live-clock {
  display: grid;
  gap: 2px;
  min-width: 142px;
  padding: 12px 14px;
  border: 1px solid rgba(140, 247, 76, 0.28);
  border-radius: 12px;
  background: rgba(1, 10, 18, 0.62);
  text-align: center;
  box-shadow: inset 0 0 24px rgba(140, 247, 76, 0.08);
}

.referee-live-clock b {
  color: #8cf74c;
  font-size: clamp(2rem, 7vw, 3.4rem);
  font-weight: 950;
  line-height: 1;
}

.referee-live-clock span {
  color: rgba(234, 248, 245, 0.72);
  font-size: 0.68rem;
}

.referee-live-meta {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(124px, 0.78fr);
  gap: 10px;
  align-items: end;
}

.referee-live-added {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 9px 10px;
  border: 1px solid rgba(42, 231, 188, 0.18);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.08);
}

.referee-live-added strong {
  color: #fff;
  font-size: 1.1rem;
  font-weight: 950;
}

.referee-live-controls {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.referee-live-controls button {
  min-height: 48px;
  padding: 8px;
  border-radius: 8px;
  font-weight: 950;
  white-space: normal;
}

.referee-low-power-toggle {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 4px 8px;
  align-items: center;
  min-width: 0;
  padding: 10px;
  border: 1px solid rgba(42, 231, 188, 0.18);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.055);
}

.referee-low-power-toggle small {
  grid-column: 2;
}

.referee-sheet-form .inline-actions button,
.referee-event-buttons button,
.referee-action-button,
.team-portal-page button,
.admin-route-shell .capture-nav button,
.admin-route-shell .admin-section-nav button {
  min-height: 44px;
}

.referee-event-buttons {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.referee-event-buttons button {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  justify-content: start;
  gap: 10px;
  min-height: 82px;
  padding: 12px;
  border: 0;
  border-radius: 10px;
  font-weight: 950;
  text-align: left;
  white-space: normal;
  box-shadow: 0 12px 26px rgba(0, 0, 0, 0.18);
  transition: transform 0.18s ease, filter 0.18s ease;
}

.referee-event-buttons button:active {
  transform: scale(0.98);
}

.referee-event-button-icon {
  display: grid;
  width: 44px;
  height: 44px;
  place-items: center;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.22);
  font-size: 1.45rem;
  line-height: 1;
}

.referee-event-button-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.referee-event-button-copy strong {
  font-size: clamp(0.82rem, 2.7vw, 1rem);
  line-height: 1;
  text-transform: uppercase;
}

.referee-event-button-copy small {
  opacity: 0.78;
  font-size: 0.68rem;
  font-weight: 950;
  text-transform: uppercase;
}

.referee-event-buttons .event-goal {
  background: linear-gradient(135deg, #0d8f42, #22e7bc 58%, #8cf74c);
  color: #03111b;
}

.referee-event-buttons .event-own-goal {
  background: linear-gradient(135deg, #0a4f7a, #0877ff);
  color: #fff;
  border: 1px solid rgba(130, 199, 255, 0.28);
}

.referee-event-buttons .event-yellow {
  background: linear-gradient(135deg, #ffd84d, #8cf74c);
  color: #241b02;
}

.referee-event-buttons .event-red {
  background: linear-gradient(135deg, #ff5959, #ff9f7a);
  color: #fff;
}

.referee-advanced-panel {
  border: 1px solid rgba(42, 231, 188, 0.18);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.055);
  overflow: hidden;
}

.referee-advanced-panel summary {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: center;
  gap: 5px;
  padding: 12px;
  cursor: pointer;
  list-style: none;
}

.referee-advanced-panel summary::-webkit-details-marker {
  display: none;
}

.referee-advanced-panel summary strong {
  color: #fff;
  font-size: 0.9rem;
  text-transform: uppercase;
}

.referee-advanced-panel summary span {
  color: rgba(234, 248, 245, 0.68);
  font-size: 0.74rem;
  font-weight: 850;
  text-align: left;
}

.referee-advanced-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  padding: 0 12px 12px;
}

.referee-event-list {
  display: grid;
  gap: 10px;
}

.referee-latest-event,
.referee-previous-events {
  display: grid;
  min-width: 0;
  gap: 8px;
}

.referee-latest-event > span {
  color: rgba(234, 248, 245, 0.7);
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.referee-previous-events {
  border: 1px solid rgba(42, 231, 188, 0.2);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.06);
  overflow: hidden;
}

.referee-previous-events summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 12px;
  cursor: pointer;
  list-style: none;
  min-width: 0;
}

.referee-previous-events summary::-webkit-details-marker {
  display: none;
}

.referee-previous-events summary::after {
  content: "+";
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 999px;
  background: rgba(140, 247, 76, 0.15);
  color: #8cf74c;
  font-size: 1.2rem;
  font-weight: 1000;
}

.referee-previous-events[open] summary::after {
  content: "-";
}

.referee-previous-events summary strong,
.referee-previous-events summary span {
  min-width: 0;
  overflow-wrap: anywhere;
}

.referee-previous-events summary span {
  color: rgba(234, 248, 245, 0.68);
  font-size: 0.78rem;
  font-weight: 900;
}

.referee-previous-event-list {
  display: grid;
  gap: 8px;
  padding: 0 10px 10px;
}

.referee-event-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  align-items: end;
  padding: 10px;
  border: 1px solid rgba(42, 231, 188, 0.18);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.08);
  min-width: 0;
}

.referee-event-row.event-side-home {
  background: linear-gradient(135deg, rgba(42, 231, 188, 0.13), rgba(255, 255, 255, 0.06));
}

.referee-event-row.event-side-away {
  background: linear-gradient(135deg, rgba(148, 163, 184, 0.16), rgba(255, 255, 255, 0.06));
}

.referee-event-row.event-kind-yellow {
  border-color: rgba(250, 204, 21, 0.52);
}

.referee-event-row.event-kind-red {
  border-color: rgba(255, 89, 89, 0.55);
}

.referee-event-row.is-latest {
  border-color: rgba(140, 247, 76, 0.45);
  background: linear-gradient(135deg, rgba(42, 231, 188, 0.15), rgba(140, 247, 76, 0.08));
}

.referee-event-row-head {
  display: flex;
  grid-column: 1 / -1;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-width: 0;
}

.referee-event-row-head > div {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.referee-event-row strong {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #8cf74c;
  overflow-wrap: anywhere;
}

.referee-event-row-head span,
.referee-locked-team span,
.referee-locked-team small {
  color: rgba(234, 248, 245, 0.68);
  font-size: 0.72rem;
  font-weight: 900;
  text-transform: uppercase;
}

.referee-locked-team {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 9px 10px;
  border: 1px solid rgba(42, 231, 188, 0.18);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.07);
}

.referee-locked-team strong {
  color: #fff;
}

.referee-player-search {
  grid-column: 1 / -1;
}

.referee-event-row input,
.referee-event-row select {
  min-width: 0;
}

.referee-event-row .danger {
  min-height: 42px;
  padding: 8px 10px;
  white-space: normal;
}

.team-portal-page {
  display: grid;
  gap: 18px;
}

.team-portal-hero {
  display: grid;
  gap: 10px;
}

.team-roster-status {
  display: grid;
  gap: 4px;
  padding: 14px;
  border-radius: 10px;
  border: 1px solid #dbe7ef;
  background: #f8fbfd;
}

.team-roster-status.open {
  border-color: color-mix(in srgb, var(--lime) 65%, #fff);
  background: color-mix(in srgb, var(--lime) 14%, #fff);
}

