.portal-bottom-nav {
  position: sticky;
  bottom: 10px;
  z-index: 30;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 4px;
  margin-top: 2px;
  padding: 8px;
  border: 1px solid rgba(91, 255, 137, 0.22);
  border-radius: 8px;
  background:
    linear-gradient(135deg, rgba(10, 37, 46, 0.94), rgba(5, 36, 24, 0.96));
  box-shadow: 0 18px 48px rgba(0, 0, 0, 0.38);
  backdrop-filter: blur(14px);
}

.portal-bottom-nav a,
.portal-bottom-nav button {
  display: grid;
  justify-items: center;
  gap: 4px;
  min-height: 52px;
  padding: 7px 4px;
  border: 0;
  border-radius: 8px;
  color: rgba(255, 255, 255, 0.72);
  background: transparent;
  font-size: 0.65rem;
  font-weight: 900;
  text-decoration: none;
}

.portal-bottom-nav .active,
.portal-bottom-nav a:focus-visible,
.portal-bottom-nav button:focus-visible {
  color: #91ff58;
  background: rgba(91, 255, 137, 0.12);
}

.portal-bottom-nav.referee .active,
.portal-bottom-nav.referee a:focus-visible,
.portal-bottom-nav.referee button:focus-visible {
  color: #77baff;
  background: rgba(29, 88, 255, 0.16);
}

.team-portal-page:not(.delegate-acta-exclusive-page) .portal-bottom-nav {
  position: fixed;
  left: 50%;
  bottom: max(10px, env(safe-area-inset-bottom));
  z-index: 42;
  width: min(calc(100% - 18px), 444px);
  margin: 0;
  transform: translateX(-50%);
}

@media (max-width: 640px) {
  .portal-board-shell {
    width: min(100% - 10px, 100%);
  }

  .portal-board-layout {
    grid-template-columns: 1fr;
  }

  .portal-side-rail {
    position: relative;
    top: auto;
    min-height: auto;
    padding: 14px;
  }

  .portal-side-brand {
    grid-template-columns: minmax(0, 1fr);
  }

  .portal-side-brand img {
    width: 150px;
  }

  .portal-side-title h1 {
    font-size: clamp(2.4rem, 13vw, 3.7rem);
  }

  .portal-side-menu {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .portal-side-menu a,
  .portal-side-menu button {
    grid-template-columns: 28px minmax(0, 1fr);
    min-height: 48px;
    padding: 7px;
    font-size: 0.7rem;
  }

  .portal-side-profile {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .portal-side-profile > b {
    grid-column: 1 / -1;
    width: fit-content;
  }

  .portal-stat-strip {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .portal-stat-strip span:first-child {
    grid-column: 1 / -1;
  }

  .portal-info-grid,
  .portal-support-grid {
    grid-template-columns: 1fr;
  }

  .portal-flow-strip {
    grid-template-columns: repeat(5, minmax(42px, 1fr));
    gap: 5px;
    padding: 7px;
  }

  .portal-flow-strip span {
    font-size: 0.55rem;
  }
}

