  font-size: clamp(0.82rem, 2vw, 1rem) !important;
  font-weight: 850 !important;
}

.tournament-entry-season::before {
  content: "";
  width: 13px;
  height: 13px;
  display: inline-block;
  margin-right: 6px;
  border: 2px solid currentColor;
  border-top-width: 4px;
  border-radius: 3px;
  vertical-align: -1px;
}

.tournament-entry-description {
  max-width: 460px;
  color: rgba(255, 255, 255, 0.68) !important;
  font-size: clamp(0.8rem, 1.85vw, 0.96rem) !important;
  font-weight: 650 !important;
  line-height: 1.45;
}

.tournament-entry-list em,
.competition-sheet-list em {
  color: var(--field-dark);
  font-size: 0.72rem;
  font-style: normal;
  font-weight: 950;
  text-align: right;
  text-transform: uppercase;
}

.tournament-entry-list em {
  display: grid;
  justify-items: center;
  gap: 4px;
  padding-left: clamp(8px, 2vw, 26px);
  border-left: 1px solid rgba(255, 255, 255, 0.14);
  color: color-mix(in srgb, var(--entry-accent) 78%, #fff);
  text-align: center;
}

.tournament-entry-list em strong {
  color: currentColor;
  font-size: clamp(2rem, 6vw, 3rem);
  line-height: 0.92;
}

.tournament-entry-list em span {
  color: rgba(255, 255, 255, 0.62);
  font-size: 0.72rem;
  font-weight: 950;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.tournament-entry-empty {
  margin: 0;
  padding: 16px clamp(14px, 3vw, 24px);
  border: 1px dashed rgba(140, 247, 76, 0.32);
  border-radius: 8px;
  background: rgba(140, 247, 76, 0.06);
  color: rgba(255, 255, 255, 0.72);
  font-weight: 850;
  line-height: 1.4;
}

.tournament-entry-chevron {
  color: rgba(255, 255, 255, 0.78);
  font-size: 2.4rem;
  font-weight: 300;
  line-height: 1;
}

.competition-mark {
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  background:
    linear-gradient(135deg, var(--mark-accent), color-mix(in srgb, var(--mark-accent) 66%, #082f25));
  color: #fff;
  font-size: 0.76rem;
  font-weight: 950;
  box-shadow: 0 10px 20px color-mix(in srgb, var(--mark-accent) 28%, transparent);
}

.tournament-entry-list .competition-mark {
  position: relative;
  width: clamp(82px, 16vw, 150px);
  height: clamp(82px, 16vw, 150px);
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--entry-accent) 72%, rgba(255, 255, 255, 0.26));
  background:
    radial-gradient(circle at 86% 86%, rgba(255, 255, 255, 0.16), transparent 35%),
    linear-gradient(135deg, color-mix(in srgb, var(--entry-accent) 86%, #0b2018), color-mix(in srgb, var(--entry-accent) 42%, #02100d));
  color: #fff;
  font-size: clamp(2.25rem, 7vw, 4.6rem);
  font-style: italic;
  letter-spacing: -0.05em;
  text-shadow: 0 4px 18px rgba(0, 0, 0, 0.3);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.12), 0 18px 36px color-mix(in srgb, var(--entry-accent) 18%, transparent);
}

.tournament-entry-list .competition-mark::after {
  content: "";
  position: absolute;
  right: -18px;
  bottom: -16px;
  width: 64px;
  height: 64px;
  border: 3px solid rgba(255, 255, 255, 0.12);
  border-radius: 50%;
}

.tournament-entry-history {
  display: grid;
  gap: 12px;
  padding: clamp(12px, 2vw, 18px);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  background: rgba(2, 12, 14, 0.48);
}

.tournament-entry-history summary {
  min-height: 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  color: rgba(255, 255, 255, 0.76);
  cursor: pointer;
  list-style: none;
}

.tournament-entry-history summary::-webkit-details-marker {
  display: none;
}

.tournament-entry-history summary span {
  color: rgba(255, 255, 255, 0.76);
  font-size: 0.82rem;
  font-weight: 950;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.tournament-entry-history summary strong {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(140, 247, 76, 0.12);
  color: #8cff45;
}

.tournament-entry-history-list {
  display: grid;
  gap: 8px;
  padding-top: 8px;
}

.tournament-entry-history-list button {
  min-width: 0;
  width: 100%;
  min-height: 68px;
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) auto 18px;
  gap: 10px;
  align-items: center;
  padding: 10px;
  border: 1px solid color-mix(in srgb, var(--entry-accent) 34%, rgba(255, 255, 255, 0.12));
  border-radius: 8px;
  background:
    radial-gradient(circle at 0% 0%, color-mix(in srgb, var(--entry-accent) 11%, transparent), transparent 34%),
    rgba(255, 255, 255, 0.05);
  color: #fff;
  text-align: left;
}

.tournament-entry-history-list button.active {
  border-color: #8cff45;
  box-shadow: 0 0 0 1px rgba(140, 247, 76, 0.22);
}

.tournament-entry-history-list .competition-mark {
  width: 42px;
  height: 42px;
}

.tournament-entry-history-list span {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.tournament-entry-history-list small {
  color: rgba(255, 255, 255, 0.6);
  font-size: 0.68rem;
  font-weight: 850;
  text-transform: uppercase;
}

.tournament-entry-history-list strong {
  min-width: 0;
  overflow-wrap: anywhere;
  color: #fff;
  font-size: 0.94rem;
  font-weight: 950;
  line-height: 1.08;
}

.tournament-entry-history-list em {
  color: color-mix(in srgb, var(--entry-accent) 76%, #fff);
  font-size: 0.7rem;
  font-style: normal;
  font-weight: 950;
  text-transform: uppercase;
  white-space: nowrap;
}

.tournament-entry-history-list b {
  color: rgba(255, 255, 255, 0.58);
  font-size: 1.6rem;
  font-weight: 300;
}

.tournament-entry-note {
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr);
  gap: 16px;
  align-items: center;
  padding: 18px clamp(16px, 3vw, 28px);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  background:
    linear-gradient(100deg, rgba(8, 44, 35, 0.74), rgba(1, 11, 14, 0.56));
}

.tournament-entry-note b {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border: 3px solid #8cff45;
  border-radius: 50%;
  color: #8cff45;
  font-family: Georgia, serif;
  font-size: 1.3rem;
  font-style: italic;
}

.tournament-entry-note strong,
.tournament-entry-note small {
  display: block;
  color: #fff;
}

.tournament-entry-note small {
  margin-top: 5px;
  color: rgba(255, 255, 255, 0.62);
  font-size: 0.9rem;
}

.tournament-entry-footer {
  position: relative;
  isolation: isolate;
  display: grid;
  justify-items: center;
  align-content: center;
  gap: 6px;
  min-height: clamp(210px, 32vw, 320px);
  overflow: hidden;
  padding: clamp(28px, 7vw, 58px) 0 clamp(34px, 8vw, 72px);
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  background:
    radial-gradient(circle at 50% 45%, rgba(140, 247, 76, 0.07), transparent 44%),
    linear-gradient(180deg, rgba(1, 10, 12, 0.22), rgba(1, 8, 10, 0.58));
  color: rgba(255, 255, 255, 0.56);
  text-align: center;
}

.tournament-entry-footer span {
  position: relative;
  z-index: 1;
  color: rgba(255, 255, 255, 0.64);
  font-size: clamp(0.72rem, 2.2vw, 0.86rem);
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  text-shadow: 0 10px 26px rgba(0, 0, 0, 0.45);
}

.tournament-entry-footer::before {
  content: "";
  position: absolute;
  inset: 18% 5% 8%;
  z-index: -1;
  background:
    radial-gradient(circle at 50% 50%, rgba(140, 247, 76, 0.1), transparent 54%),
    radial-gradient(circle at 50% 60%, rgba(35, 180, 255, 0.08), transparent 48%);
  filter: blur(10px);
  pointer-events: none;
}

.tournament-entry-footer img {
  position: relative;
  z-index: 0;
  width: min(480px, 86vw);
  height: auto;
  display: block;
  margin-top: -6px;
  opacity: 0.32;
  filter:
    grayscale(0.18)
    saturate(0.9)
    drop-shadow(0 22px 54px rgba(0, 0, 0, 0.48));
  mix-blend-mode: screen;
}

.public-competition-dock {
  position: sticky;
  top: 10px;
  z-index: 35;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  margin: -22px auto 14px;
  width: min(100%, 880px);
  padding: 10px;
  border: 1px solid color-mix(in srgb, var(--competition-accent) 44%, rgba(255, 255, 255, 0.8));
  border-radius: 8px;
  background:
    radial-gradient(circle at 0% 0%, color-mix(in srgb, var(--competition-accent) 18%, transparent), transparent 38%),
    rgba(255, 255, 255, 0.94);
  box-shadow: 0 16px 42px rgba(2, 12, 20, 0.14);
  backdrop-filter: blur(18px) saturate(1.2);
}

.public-competition-dock > div:first-child {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
}

.public-competition-dock span {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.public-competition-dock small,
.public-competition-dock dt {
  color: var(--muted);
  font-size: 0.65rem;
  font-weight: 950;
  text-transform: uppercase;
}

.public-competition-dock strong {
  overflow-wrap: anywhere;
  color: var(--field-dark);
  font-size: 1rem;
  line-height: 1.05;
}

.public-competition-dock > button {
  min-height: 40px;
  border: 1px solid color-mix(in srgb, var(--competition-accent) 70%, var(--field));
  background: #fff;
  color: var(--field-dark);
  font-size: 0.78rem;
  white-space: nowrap;
}

.public-competition-dock dl {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin: 0;
}

.public-competition-dock dl > div {
  min-width: 0;
  padding: 8px 10px;
  border: 1px solid color-mix(in srgb, var(--competition-accent) 20%, var(--line));
  border-radius: 8px;
  background: color-mix(in srgb, var(--competition-accent) 7%, #fff);
}

.public-competition-dock dd {
  margin: 2px 0 0;
  color: var(--field-dark);
  font-size: 1.05rem;
  font-weight: 950;
}

.competition-sheet-backdrop {
  position: fixed;
  inset: 0;
  z-index: 70;
  display: grid;
  align-items: end;
  background: rgba(2, 8, 6, 0.52);
  backdrop-filter: blur(6px);
}

.competition-sheet {
  width: min(100%, 520px);
  max-height: min(82svh, 720px);
  overflow: auto;
  justify-self: center;
  display: grid;
  gap: 14px;
  padding: 16px;
  border-radius: 8px 8px 0 0;
  background: #fff;
  box-shadow: 0 -18px 54px rgba(2, 8, 6, 0.24);
}

.competition-sheet-head {
  display: flex;
  justify-content: space-between;
  align-items: start;
  gap: 12px;
}

.competition-sheet-head div {
  min-width: 0;
  display: grid;
  gap: 4px;
}

.competition-sheet-head span {
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 950;
  text-transform: uppercase;
}

.competition-sheet-head strong {
  color: var(--field-dark);
  font-size: 1.08rem;
  line-height: 1.1;
}

.competition-sheet-head button {
  width: 36px;
  height: 36px;
  padding: 0;
  border: 1px solid var(--line);
  background: #fff;
  color: var(--field-dark);
}

.competition-sheet-list button {
  border-color: var(--line);
  box-shadow: 0 10px 24px rgba(23, 33, 28, 0.08);
}

.public-search-results small {
  color: color-mix(in srgb, var(--field) 78%, var(--muted));
  font-size: 0.68rem;
  font-weight: 950;
  text-transform: uppercase;
}

@media (min-width: 760px) {
