  width: min(100%, 760px);
  margin: 0 auto;
  padding: 0 12px;
  background: transparent;
  border: 0;
  box-shadow: none;
}

.public-league-page.public-view-inicio .public-home-view,
.public-league-page.public-view-inicio .public-home-dashboard {
  display: block;
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
}

.home-app-shell {
  display: grid;
  gap: 18px;
  padding: 18px 0 8px;
}

.home-app-header {
  min-height: 54px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 4px 2px 0;
}

.home-brand-lockup {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.home-brand-lockup img {
  width: 34px;
  height: 34px;
  object-fit: contain;
  filter: drop-shadow(0 10px 20px rgba(20, 149, 255, 0.24));
}

.home-brand-lockup span {
  color: #ffffff;
  font-size: 1rem;
  font-weight: 1000;
  letter-spacing: 0.02em;
}

.home-icon-button {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(119, 159, 204, 0.18);
  border-radius: 16px;
  background:
    linear-gradient(180deg, rgba(9, 28, 50, 0.92), rgba(4, 12, 22, 0.88));
  color: var(--home-blue);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06), 0 14px 28px rgba(0, 0, 0, 0.26);
}

.home-icon-button svg {
  width: 22px;
  height: 22px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 2;
}

.home-league-intro {
  display: grid;
  gap: 4px;
  padding: 4px 2px 0;
}

.home-league-intro span,
.home-section-head button,
.home-announcement-card span,
.home-moment-card span,
.home-featured-top span,
.home-highlight-card span {
  color: var(--home-green);
  font-size: 0.68rem;
  font-weight: 1000;
  letter-spacing: 0.01em;
  text-transform: uppercase;
}

.home-league-intro h1 {
  margin: 0;
  color: #ffffff;
  font-size: clamp(1.42rem, 8vw, 2.35rem);
  font-weight: 1000;
  line-height: 0.98;
  letter-spacing: 0;
}

.home-league-intro small {
  color: var(--home-muted);
  font-size: 0.78rem;
  font-weight: 850;
}

.home-featured-match {
  position: relative;
  display: grid;
  gap: 16px;
  overflow: hidden;
  min-height: 310px;
  padding: 18px;
  border: 1px solid rgba(20, 149, 255, 0.24);
  border-radius: 22px;
  background:
    linear-gradient(180deg, rgba(3, 10, 20, 0.1), rgba(2, 8, 15, 0.92)),
    var(--home-photo) center / cover;
  box-shadow:
    0 22px 52px rgba(0, 0, 0, 0.38),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.home-featured-match::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 50% 18%, rgba(20, 149, 255, 0.28), transparent 42%),
    linear-gradient(180deg, rgba(1, 7, 13, 0.1), rgba(1, 6, 12, 0.82));
  pointer-events: none;
}

.home-featured-match > * {
  position: relative;
  z-index: 1;
}

.home-featured-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.home-featured-top strong {
  padding: 7px 14px;
  border-radius: 999px;
  background: linear-gradient(135deg, var(--home-green), #1bd8e9);
  color: #02101a;
  font-size: 0.78rem;
  font-weight: 1000;
}

.home-featured-teams {
  align-self: center;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: 10px;
}

.home-featured-teams div {
  display: grid;
  justify-items: center;
  gap: 8px;
  min-width: 0;
}

.home-featured-teams strong {
  max-width: 100%;
  color: #ffffff;
  font-size: clamp(0.72rem, 3vw, 0.92rem);
  font-weight: 1000;
  line-height: 1.05;
  text-align: center;
  text-wrap: balance;
}

.home-featured-teams em {
  width: 58px;
  height: 58px;
  display: grid;
  place-items: center;
  border-radius: 20px;
  background: rgba(3, 12, 22, 0.64);
  color: #ffffff;
  font-size: 1.35rem;
  font-style: normal;
  font-weight: 1000;
  box-shadow: inset 0 0 0 1px rgba(216, 226, 241, 0.12);
}

.home-featured-crest {
  width: 76px;
  height: 76px;
  border-radius: 24px;
  box-shadow: 0 16px 32px rgba(0, 0, 0, 0.36);
}

.home-featured-meta {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.home-featured-meta span {
  min-height: 38px;
  display: grid;
  place-items: center;
  padding: 8px;
  border-radius: 13px;
  background: rgba(3, 12, 22, 0.58);
  color: rgba(248, 251, 255, 0.86);
  font-size: 0.68rem;
  font-weight: 850;
  line-height: 1.1;
  text-align: center;
}

.home-featured-match button {
  min-height: 50px;
  border: 0;
  border-radius: 15px;
  background: linear-gradient(135deg, var(--home-green), #18d5e6);
  color: #021019;
  font-size: 0.82rem;
  font-weight: 1000;
  box-shadow: 0 16px 32px rgba(18, 210, 190, 0.18);
}

.home-announcement-card,
.home-next-panel,
.home-standings-preview,
.home-gallery-panel,
.home-moment-card,
.home-week-highlights {
  overflow: hidden;
  border: 1px solid var(--home-line);
  border-radius: 20px;
  background:
    radial-gradient(circle at 100% 0%, rgba(20, 149, 255, 0.14), transparent 36%),
    linear-gradient(180deg, rgba(10, 25, 43, 0.88), rgba(5, 14, 25, 0.9));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.045), 0 18px 38px rgba(0, 0, 0, 0.22);
}

.home-announcement-card {
  display: grid;
  gap: 8px;
  padding: 16px;
}

.home-announcement-card strong,
.home-section-head h2,
.home-moment-card strong {
  margin: 0;
  color: #ffffff;
  font-size: 1.02rem;
  font-weight: 1000;
  line-height: 1.08;
}

.home-announcement-card p,
.home-moment-card p {
  margin: 0;
  color: rgba(216, 226, 241, 0.74);
  font-size: 0.78rem;
  font-weight: 700;
  line-height: 1.45;
}

.home-announcement-card button,
.home-section-head button {
  justify-self: start;
  padding: 0;
  border: 0;
  background: transparent;
}

.home-week-highlights,
.home-next-panel,
.home-standings-preview,
.home-gallery-panel {
  display: grid;
  gap: 12px;
  padding: 16px;
}

.home-section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.home-section-head h2 {
  font-size: 1rem;
}

.home-highlight-strip {
  display: grid;
  grid-template-columns: repeat(4, minmax(112px, 1fr));
  gap: 10px;
  overflow-x: auto;
  padding-bottom: 2px;
  scrollbar-width: none;
}

.home-highlight-strip::-webkit-scrollbar {
  display: none;
}

.home-highlight-card {
  min-height: 156px;
  display: grid;
  align-content: start;
  gap: 8px;
  padding: 12px;
  border: 1px solid rgba(119, 159, 204, 0.14);
  border-radius: 16px;
  background: rgba(3, 12, 22, 0.58);
}

.home-highlight-crest {
  width: 56px;
  height: 56px;
  border-radius: 18px;
}

.home-highlight-card strong {
  color: #ffffff;
  font-size: 0.78rem;
  font-weight: 1000;
  line-height: 1.1;
}

.home-highlight-card small {
  color: var(--home-green);
  font-size: 0.7rem;
  font-weight: 900;
}

.home-moment-card {
  position: relative;
  min-height: 260px;
  display: grid;
  align-content: end;
}

.home-moment-card img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.82;
}

.home-moment-card::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 8%, rgba(1, 7, 13, 0.9) 86%);
}

.home-moment-card div {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 7px;
  padding: 18px;
}

.home-next-list {
  display: grid;
  gap: 10px;
}

.public-league-page.public-view-inicio .mini-match-row {
  width: 100%;
  min-height: 76px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  padding: 12px;
  border: 1px solid rgba(119, 159, 204, 0.13);
  border-radius: 16px;
  background: rgba(3, 12, 22, 0.62);
  color: #ffffff;
  text-align: left;
}

.public-league-page.public-view-inicio .mini-match-row small {
  grid-column: 1 / -1;
  color: rgba(216, 226, 241, 0.62);
  font-size: 0.68rem;
  font-weight: 800;
  text-align: center;
}

.public-league-page.public-view-inicio .mini-match-row > strong {
  color: var(--home-blue);
  font-size: 0.9rem;
  font-weight: 1000;
}

.public-league-page.public-view-inicio .mini-match-team {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  color: #ffffff;
  font-size: 0.68rem;
  font-weight: 950;
}

.public-league-page.public-view-inicio .mini-match-team.away {
  justify-content: end;
  text-align: right;
}

.public-league-page.public-view-inicio .mini-match-crest {
  width: 30px;
  height: 30px;
  border-radius: 10px;
}

.home-standings-list {
  display: grid;
  gap: 4px;
}

.home-standings-list article {
  min-height: 48px;
  display: grid;
  grid-template-columns: 26px 34px minmax(0, 1fr) 42px 42px;
  align-items: center;
  gap: 8px;
  border-bottom: 1px solid rgba(119, 159, 204, 0.1);
}

.home-standings-list span {
  color: var(--home-blue);
  font-weight: 1000;
  text-align: center;
}

.home-table-crest {
  width: 30px;
  height: 30px;
  border-radius: 10px;
}

.home-standings-list strong {
  overflow: hidden;
  color: #ffffff;
  font-size: 0.76rem;
  font-weight: 950;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.home-standings-list small {
  color: rgba(216, 226, 241, 0.64);
  font-size: 0.66rem;
  font-weight: 850;
  text-align: right;
}

.home-standings-list em {
  color: var(--home-blue);
  font-style: normal;
  font-weight: 1000;
  text-align: right;
}

.home-stat-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.home-stat-grid article {
  min-height: 102px;
  display: grid;
  align-content: center;
  gap: 4px;
  padding: 16px;
  border: 1px solid var(--home-line);
  border-radius: 18px;
  background:
    radial-gradient(circle at 100% 0%, rgba(20, 149, 255, 0.16), transparent 42%),
    rgba(8, 23, 39, 0.88);
}

.home-stat-grid strong {
  color: #ffffff;
  font-size: 1.55rem;
  font-weight: 1000;
}

.home-stat-grid span {
  color: rgba(216, 226, 241, 0.72);
  font-size: 0.72rem;
  font-weight: 850;
}

.home-gallery-grid {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  grid-auto-rows: 92px;
  gap: 8px;
}

.home-gallery-grid figure {
  position: relative;
  overflow: hidden;
  min-width: 0;
  margin: 0;
  border-radius: 15px;
  background: rgba(3, 12, 22, 0.72);
}

.home-gallery-grid figure:first-child {
  grid-row: span 2;
}

.home-gallery-grid img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.home-gallery-grid figcaption {
  position: absolute;
  inset: auto 8px 8px;
  overflow: hidden;
  color: #ffffff;
  font-size: 0.66rem;
  font-weight: 950;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.72);
}

.public-league-page.public-view-inicio .sponsor-public-strip,
.public-league-page.public-view-inicio .sponsor-empty {
  border-color: var(--home-line);
  border-radius: 20px;
  background: rgba(8, 23, 39, 0.88);
}

.public-league-page.public-view-inicio .public-quick-nav {
  position: fixed;
  inset: auto max(10px, calc((100vw - 760px) / 2 + 10px)) 10px;
  top: auto;
  z-index: 80;
  width: auto;
  max-width: 740px;
  min-height: 82px;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 6px;
  margin: 0;
  padding: 9px;
  border: 1px solid rgba(95, 147, 199, 0.22);
  border-radius: 28px;
  background:
    radial-gradient(circle at 50% 0%, rgba(13, 139, 255, 0.16), transparent 45%),
    linear-gradient(180deg, rgba(3, 12, 22, 0.94), rgba(1, 7, 13, 0.98));
  box-shadow:
    0 22px 48px rgba(0, 0, 0, 0.46),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(18px) saturate(1.25);
}

.public-league-page.public-view-inicio .public-quick-nav button {
  min-height: 64px;
  flex-direction: column;
  gap: 4px;
  padding: 7px 4px;
  border: 1px solid transparent;
  border-radius: 20px;
  background: transparent;
  color: rgba(216, 226, 241, 0.66);
  font-size: 0.7rem;
  line-height: 1;
  outline: none;
  transform: none;
}

.public-league-page.public-view-inicio .public-quick-nav button.active,
.public-league-page.public-view-inicio .public-quick-nav button[aria-current="page"] {
  border-color: rgba(13, 139, 255, 0.42);
  color: var(--home-blue);
  box-shadow: inset 0 0 0 1px rgba(13, 139, 255, 0.12);
}

.public-league-page.public-view-inicio .public-quick-nav button::before {
  background:
    linear-gradient(180deg, rgba(13, 139, 255, 0.22), rgba(13, 139, 255, 0.08)),
    rgba(7, 43, 84, 0.7);
  opacity: 0;
  transform: scale(0.94);
}

.public-league-page.public-view-inicio .public-quick-nav button.active::before,
.public-league-page.public-view-inicio .public-quick-nav button[aria-current="page"]::before {
  opacity: 1;
  transform: scale(1);
}

.public-league-page.public-view-inicio .quick-nav-icon {
  width: 30px;
  height: 30px;
  color: currentColor;
  filter: none;
}

.public-league-page.public-view-inicio .quick-nav-icon svg {
  width: 28px;
  height: 28px;
  stroke-width: 1.9;
}

.public-media-admin {
  display: grid;
  gap: 14px;
  margin: 16px 0;
  padding: 16px;
  border: 1px solid rgba(79, 240, 152, 0.16);
  border-radius: 22px;
  background:
    radial-gradient(circle at 100% 0%, rgba(24, 213, 230, 0.14), transparent 36%),
    linear-gradient(180deg, rgba(4, 23, 32, 0.92), rgba(3, 16, 24, 0.88));
}

.public-media-admin-head,
.public-media-admin-head > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.public-media-admin-head > div {
  justify-content: start;
  min-width: 0;
}

.public-media-admin-head span {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  background: rgba(24, 213, 230, 0.12);
  color: #18d5e6;
}

.public-media-admin-head span svg {
  width: 22px;
  height: 22px;
}

.public-media-admin-head strong {
  color: #ffffff;
  font-size: 1rem;
  font-weight: 1000;
}

.public-media-admin-head small,
.public-media-admin-head em {
  color: rgba(216, 226, 241, 0.66);
  font-size: 0.72rem;
  font-style: normal;
  font-weight: 800;
}

.public-media-scope-bar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: 10px;
  padding: 12px;
  border: 1px solid rgba(119, 159, 204, 0.13);
  border-radius: 18px;
  background:
    linear-gradient(135deg, rgba(13, 139, 255, 0.1), rgba(24, 213, 230, 0.06)),
    rgba(2, 10, 18, 0.52);
}

.public-media-scope-bar label {
  display: grid;
  gap: 7px;
  min-width: 0;
  color: rgba(216, 226, 241, 0.72);
  font-size: 0.68rem;
  font-weight: 900;
  letter-spacing: 0;
  text-transform: uppercase;
}

.public-media-scope-bar select {
  width: 100%;
  min-height: 42px;
  border: 1px solid rgba(119, 159, 204, 0.18);
  border-radius: 14px;
  background: rgba(5, 20, 32, 0.94);
  color: #ffffff;
  font-size: 0.88rem;
  font-weight: 900;
  outline: none;
}

.public-media-scope-bar span {
  justify-self: end;
  max-width: 220px;
  padding: 10px 12px;
  border-radius: 999px;
  background: rgba(13, 139, 255, 0.14);
  color: #8fc7ff;
  font-size: 0.72rem;
  font-weight: 1000;
  text-align: right;
}

.public-media-admin-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.public-media-admin-summary article {
  display: grid;
  gap: 2px;
  padding: 12px;
  border: 1px solid rgba(119, 159, 204, 0.13);
  border-radius: 15px;
  background: rgba(2, 10, 18, 0.48);
}

.public-media-admin-summary strong {
  color: #78f24a;
  font-size: 1.35rem;
  font-weight: 1000;
}

.public-media-admin-summary span {
  color: rgba(216, 226, 241, 0.68);
  font-size: 0.68rem;
  font-weight: 900;
}

.public-media-form,
.public-media-card form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.public-media-form .wide-field,
.public-media-card form .wide-field,
.public-media-form button,
.public-media-card .announcement-card-actions {
  grid-column: 1 / -1;
}

.public-media-list {
  display: grid;
  gap: 10px;
}

.public-media-card {
  overflow: hidden;
  border: 1px solid rgba(119, 159, 204, 0.13);
  border-radius: 16px;
  background: rgba(2, 10, 18, 0.5);
}

.public-media-card summary {
  min-height: 78px;
  display: grid;
  grid-template-columns: 72px minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  padding: 10px;
  cursor: pointer;
}

.public-media-card summary img {
  width: 72px;
  height: 58px;
  border-radius: 12px;
  object-fit: cover;
}

.league-sponsor-admin .public-media-card summary img {
  object-fit: contain;
  padding: 8px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.03)),
    rgba(255, 255, 255, 0.04);
}

.public-media-card summary strong {
  color: #ffffff;
  font-size: 0.86rem;
  font-weight: 1000;
}

.public-media-card summary small,
.public-media-card summary em {
  color: rgba(216, 226, 241, 0.66);
  font-size: 0.68rem;
  font-style: normal;
  font-weight: 800;
}

.public-media-card form {
  padding: 0 10px 12px;
}

@media (max-width: 520px) {
  .home-app-shell {
    gap: 16px;
    padding-top: 14px;
  }

  .home-featured-match {
    min-height: 292px;
    padding: 16px;
  }

  .home-featured-meta {
    grid-template-columns: 1fr;
  }

  .home-highlight-strip {
    grid-template-columns: repeat(4, 112px);
  }

  .home-stat-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .home-stat-grid article {
    min-height: 94px;
    padding: 13px;
  }

  .home-gallery-grid {
    grid-auto-rows: 84px;
  }

  .public-media-form,
  .public-media-card form {
    grid-template-columns: 1fr;
  }

  .public-media-scope-bar {
    grid-template-columns: 1fr;
  }

  .public-media-scope-bar span {
    justify-self: stretch;
    max-width: none;
    text-align: left;
  }

  .public-media-card summary {
    grid-template-columns: 64px minmax(0, 1fr);
  }

  .public-media-card summary em {
    display: none;
  }
}

/* Final priority overrides for the public home redesign. */
.public-league-page.public-view-inicio .public-hero,
.public-league-page.public-view-inicio .identity-strip,
.public-league-page.public-view-inicio .public-pulse-bar,
.public-league-page.public-view-inicio .spotlight-strip,
.public-league-page.public-view-inicio .announcement-public-panel {
  display: none !important;
}

.public-league-page.public-view-inicio .public-topbar {
  display: none !important;
}

body:has(.public-league-page.public-view-inicio) .public-topbar {
  display: none !important;
}

/* Public teams redesign: directory + roster screens. */
body:has(.public-league-page.public-view-equipos) .public-topbar {
  display: none !important;
}

.public-league-page.public-view-equipos {
  --teams-blue: #0d8bff;
  --teams-blue-soft: rgba(13, 139, 255, 0.14);
  --teams-line: rgba(148, 163, 184, 0.18);
  --teams-panel: rgba(5, 13, 24, 0.88);
  --teams-panel-strong: rgba(8, 18, 31, 0.96);
  background:
    radial-gradient(circle at 76% 0%, rgba(13, 139, 255, 0.22), transparent 38%),
    linear-gradient(180deg, #020711 0%, #04111d 52%, #020711 100%);
}

.public-league-page.public-view-equipos .public-app-workspace {
  max-width: min(100%, 980px);
  margin: 0 auto;
  padding: 14px clamp(10px, 3vw, 18px) 112px;
}

.public-league-page.public-view-equipos #equipos {
  overflow: hidden;
  gap: 16px;
  min-height: 100svh;
  padding: clamp(14px, 3vw, 24px);
  border: 1px solid var(--teams-line);
  border-radius: 24px;
  background:
    radial-gradient(circle at 10% 0%, rgba(13, 139, 255, 0.14), transparent 32%),
    linear-gradient(180deg, rgba(2, 8, 17, 0.94), rgba(4, 12, 22, 0.98));
  box-shadow: 0 24px 62px rgba(0, 0, 0, 0.34);
}

.public-league-page.public-view-equipos .public-screen-header {
  align-items: center;
  padding-bottom: 16px;
  border-bottom-color: rgba(148, 163, 184, 0.16);
}

.public-league-page.public-view-equipos .public-screen-header div {
  text-align: right;
}

.public-league-page.public-view-equipos .public-screen-header span {
  color: var(--teams-blue);
  font-size: 0.74rem;
  letter-spacing: 0;
}

.public-league-page.public-view-equipos .public-screen-header strong {
  color: #ffffff;
  font-size: clamp(1.55rem, 5vw, 2.35rem);
  line-height: 1.02;
}

.public-league-page.public-view-equipos .public-screen-back,
.public-league-page.public-view-equipos .public-inline-back {
  min-height: 46px;
  border-color: rgba(13, 139, 255, 0.36);
  border-radius: 999px;
  background:
    linear-gradient(180deg, rgba(13, 139, 255, 0.12), rgba(13, 139, 255, 0.05)),
    rgba(3, 12, 24, 0.86);
  color: #f8fbff;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.04);
}

.public-team-directory,
.public-team-roster-screen {
  display: grid;
  gap: 14px;
}

.public-team-directory-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 62px;
  align-items: center;
  gap: 12px;
  min-height: 112px;
  padding: 18px;
  border: 1px solid rgba(13, 139, 255, 0.22);
  border-radius: 22px;
  background:
    radial-gradient(circle at 88% 18%, rgba(13, 139, 255, 0.32), transparent 34%),
    linear-gradient(135deg, rgba(8, 36, 64, 0.88), rgba(5, 14, 26, 0.94));
}

.public-team-directory-hero span,
.public-team-roster-hero span,
.public-team-roster-fixtures article > span,
.public-team-roster-group h3 {
  color: var(--teams-blue);
  font-size: 0.72rem;
  font-weight: 1000;
  text-transform: uppercase;
}

.public-team-directory-hero strong {
  display: block;
  margin-top: 4px;
  color: #ffffff;
  font-size: clamp(1.35rem, 5vw, 2rem);
  font-weight: 1000;
  line-height: 1.04;
  overflow-wrap: anywhere;
}

.public-team-directory-hero small,
.public-team-roster-hero small {
  display: block;
  margin-top: 5px;
  color: rgba(226, 232, 240, 0.74);
  font-weight: 850;
  line-height: 1.28;
  overflow-wrap: anywhere;
}

.public-team-directory-hero em {
  width: 58px;
  height: 58px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(13, 139, 255, 0.34);
  border-radius: 50%;
  background: var(--teams-blue-soft);
  color: #ffffff;
  font-size: 1.45rem;
  font-style: normal;
  font-weight: 1000;
}

.public-team-list {
  display: grid;
  gap: 10px;
}

.public-team-list-card {
  position: relative;
  min-width: 0;
  display: grid;
  grid-template-columns: 34px 52px minmax(0, 1fr) auto 24px;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-height: 86px;
  padding: 12px 10px;
  border: 1px solid rgba(148, 163, 184, 0.16);
  border-radius: 18px;
  background:
    linear-gradient(135deg, rgba(13, 139, 255, 0.08), transparent 38%),
    rgba(7, 17, 30, 0.88);
  color: #ffffff;
  cursor: pointer;
  font: inherit;
  text-align: left;
  transition: transform 180ms ease, border-color 180ms ease, background 180ms ease;
}

.public-team-list-card::before {
  content: "";
  position: absolute;
  inset: 10px auto 10px 0;
  width: 4px;
  border-radius: 0 999px 999px 0;
  background: var(--teams-blue);
  opacity: 0.82;
}

.public-team-list-card:hover,
.public-team-list-card:focus-visible {
  border-color: rgba(13, 139, 255, 0.58);
  background:
    linear-gradient(135deg, rgba(13, 139, 255, 0.16), transparent 44%),
    rgba(8, 20, 36, 0.96);
  transform: translateY(-1px);
  outline: none;
}

.public-team-rank {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: rgba(13, 139, 255, 0.16);
  color: #9ed0ff;
  font-size: 0.75rem;
  font-weight: 1000;
}

.public-team-list-crest {
  width: 48px;
  height: 48px;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 16px;
  box-shadow: 0 14px 26px rgba(0, 0, 0, 0.28);
}

.public-team-list-main {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.public-team-list-main strong {
  color: #ffffff;
  font-size: 0.98rem;
  font-weight: 1000;
  line-height: 1.08;
  overflow-wrap: anywhere;
}

.public-team-list-main small,
.public-team-list-main em {
  color: rgba(226, 232, 240, 0.7);
  font-size: 0.72rem;
  font-style: normal;
  font-weight: 850;
  line-height: 1.2;
  overflow-wrap: anywhere;
}

.public-team-list-main em {
  color: #8fc7ff;
}

.public-team-list-stats {
  display: grid;
  grid-template-columns: repeat(2, 44px);
  gap: 6px;
}

.public-team-list-stats span,
.public-team-roster-stats span,
.public-team-player-stats {
  display: grid;
  place-items: center;
  gap: 1px;
  min-height: 42px;
  border: 1px solid rgba(148, 163, 184, 0.14);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.045);
}

.public-team-list-stats strong,
.public-team-roster-stats strong,
.public-team-player-stats strong {
  color: #ffffff;
  font-size: 0.95rem;
  font-weight: 1000;
  line-height: 1;
}

.public-team-list-stats small,
.public-team-roster-stats small,
.public-team-player-stats small {
  color: rgba(226, 232, 240, 0.58);
  font-size: 0.55rem;
  font-weight: 950;
  text-transform: uppercase;
}

.public-team-card-chevron,
.public-team-player-row > em {
  color: #ffffff;
  font-size: 1.9rem;
  font-style: normal;
  font-weight: 300;
  line-height: 1;
  opacity: 0.82;
}

.public-team-roster-back {
  justify-self: start;
}

.public-team-roster-hero {
  display: grid;
  grid-template-columns: 86px minmax(0, 1fr);
  align-items: center;
  gap: 14px;
  padding: 16px;
  border: 1px solid rgba(13, 139, 255, 0.24);
  border-radius: 24px;
  background:
    radial-gradient(circle at 90% 12%, rgba(13, 139, 255, 0.28), transparent 38%),
    linear-gradient(135deg, rgba(8, 35, 63, 0.86), rgba(4, 12, 22, 0.96));
}

.public-team-roster-crest {
  width: 78px;
  height: 78px;
  border: 2px solid rgba(255, 255, 255, 0.24);
  border-radius: 24px;
  font-size: 1.1rem;
}

.public-team-roster-hero strong {
  display: block;
  margin-top: 3px;
  color: #ffffff;
  font-size: clamp(1.45rem, 6vw, 2.25rem);
  font-weight: 1000;
  line-height: 1;
  overflow-wrap: anywhere;
}

.public-team-roster-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.public-team-roster-stats span {
  min-height: 68px;
  border-radius: 18px;
}

.public-team-roster-stats strong {
  color: var(--teams-blue);
  font-size: 1.35rem;
}

.public-team-roster-fixtures {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.public-team-roster-fixtures article {
  display: grid;
  gap: 8px;
  min-width: 0;
  padding: 13px;
  border: 1px solid rgba(148, 163, 184, 0.14);
  border-radius: 18px;
  background: rgba(7, 17, 30, 0.74);
  color: #ffffff;
}

.public-team-roster-fixtures .versus-line {
  gap: 6px;
}

.public-team-roster-fixtures .versus-line strong {
  font-size: 0.72rem;
}

.public-team-roster-fixtures .match-meta span {
  color: rgba(226, 232, 240, 0.68);
}

.public-team-roster-list {
  display: grid;
  gap: 13px;
}

.public-team-roster-group {
  display: grid;
  gap: 8px;
}

.public-team-roster-group h3 {
  margin: 4px 0 0;
  padding: 0 2px;
}

.public-team-player-row {
  min-width: 0;
  display: grid;
  grid-template-columns: 44px 42px minmax(0, 1fr) 58px 18px;
  align-items: center;
  gap: 9px;
  width: 100%;
  min-height: 72px;
  padding: 10px;
  border: 1px solid rgba(148, 163, 184, 0.14);
  border-radius: 18px;
  background: rgba(7, 17, 30, 0.82);
  color: #ffffff;
  cursor: pointer;
  font: inherit;
  text-align: left;
}

.public-team-player-row:hover,
.public-team-player-row:focus-visible {
  border-color: rgba(13, 139, 255, 0.5);
  outline: none;
}

.public-team-player-avatar {
  width: 42px;
  height: 42px;
  font-size: 0.72rem;
}

.public-team-player-number {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(13, 139, 255, 0.36);
  border-radius: 13px;
  background: rgba(13, 139, 255, 0.11);
  color: #b9dcff;
  font-size: 0.9rem;
  font-weight: 1000;
}

.public-team-player-info {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.public-team-player-info strong {
  color: #ffffff;
  font-size: 0.88rem;
  font-weight: 1000;
  line-height: 1.12;
  overflow-wrap: anywhere;
}

.public-team-player-info small {
  color: rgba(226, 232, 240, 0.62);
  font-size: 0.68rem;
  font-weight: 850;
  line-height: 1.2;
  overflow-wrap: anywhere;
}

.public-team-player-stats {
  min-height: 44px;
  border-radius: 14px;
}

@media (max-width: 620px) {
  .public-league-page.public-view-equipos .public-app-workspace {
    padding-inline: 8px;
    padding-bottom: 104px;
  }

  .public-league-page.public-view-equipos #equipos {
    border-radius: 0;
    border-inline: 0;
    padding: 12px;
  }

  .public-league-page.public-view-equipos .public-screen-header {
    align-items: stretch;
    flex-direction: column-reverse;
  }

  .public-league-page.public-view-equipos .public-screen-header div {
    text-align: left;
  }

  .public-team-directory-hero {
    grid-template-columns: minmax(0, 1fr) 54px;
    min-height: 104px;
    padding: 15px;
  }

  .public-team-list-card {
    grid-template-columns: 30px 48px minmax(0, 1fr) 18px;
    min-height: 92px;
    padding: 11px 9px;
  }

  .public-team-list-stats {
    grid-column: 3 / 5;
    grid-row: 2;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    justify-self: stretch;
  }

  .public-team-card-chevron {
    grid-column: 4;
    grid-row: 1;
  }

  .public-team-roster-hero {
    grid-template-columns: 72px minmax(0, 1fr);
    padding: 14px;
  }

  .public-team-roster-crest {
    width: 66px;
    height: 66px;
    border-radius: 20px;
  }

  .public-team-roster-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .public-team-roster-fixtures {
    grid-template-columns: 1fr;
  }

  .public-team-player-row {
    grid-template-columns: 40px 36px minmax(0, 1fr) 16px;
  }

  .public-team-player-stats {
    grid-column: 3 / 5;
    grid-row: 2;
    justify-items: start;
    min-height: 30px;
    padding: 0 10px;
  }

  .public-team-player-stats strong,
  .public-team-player-stats small {
    display: inline;
  }
}

